 3→using Avalonia;
 4→using Avalonia.ReactiveUI;
 5→using DemoApp.Shared;
 6→using Microsoft.Extensions.DependencyInjection;
 7→using Microsoft.Extensions.Hosting;
 8→using Microsoft.Extensions.Logging;
 9→using Six.Avalonia.Mcp.Connector;
10→
11→namespace DemoApp.CollaborativeEditor;
12→
13→sealed class Program
14→{
15→  [STAThread]
16→  public static void Main(string[] args)
17→  {
18→    IHost host = CreateHostBuilder(args).Build();
19→    App.Services = host.Services;
20→
21→    _ = host.StartAsync();
22→
23→    BuildAvaloniaApp()
24→      .StartWithClassicDesktopLifetime(args);
25→  }
26→
27→  public static IHostBuilder CreateHostBuilder(string[] args) =>
28→    Host.CreateDefaultBuilder(args)
29→      .ConfigureLogging(logging =>
30→      {
31→        logging.ClearProviders();
32→        logging.AddDebug();
33→        logging.AddConsole();
34→        logging.SetMinimumLevel(LogLevel.Trace);
35→      })
36→      .AddServiceDefaults()
37→#if DEBUG
38→      .AddAvaloniaMcpConnector(options => options.AppName = "CollaborativeEditor")
39→#endif
40→      .ConfigureServices((context, services) =>
41→      {
42→        services.AddSingleton(new RepoServiceOptions
43→        {
44→          HubPath = "/hubs/editor",
45→          AppName = "CollaborativeEditor"
46→        });
47→        services.AddSingleton<RepoService>();
48→      });
49→
50→  public static AppBuilder BuildAvaloniaApp()
51→    => AppBuilder.Configure<App>()
52→      .UsePlatformDetect()
53→      .WithInterFont()
54→      .LogToTrace()
55→      .UseReactiveUI();
56→}
