  3→using System.Reactive;
  4→using DemoApp.CollaborativeEditor.Models;
  5→using DemoApp.CollaborativeEditor.Services;
  6→using DemoApp.Shared;
  7→using Microsoft.Extensions.Logging;
  8→using Microsoft.Extensions.Logging.Abstractions;
  9→using Six.Automerge;
 10→using Six.Automerge.Repository;
 11→using ReactiveUI;
 12→
 13→namespace DemoApp.CollaborativeEditor.ViewModels;
 14→
 15→public class EditorViewModel : ViewModelBase, IDisposable
 16→{
 17→  readonly RepoService? _repoService;
 18→  readonly ILogger<EditorViewModel> _logger;
 19→  readonly Action<Action> _dispatcher;
 20→  AutomergeService? _automergeService;
 21→  DocHandle<object>? _docHandle;
 22→  AutomergeCursor? _savedCursor;
 23→  string _documentText = string.Empty;
 24→  string _syncStatus = "Disconnected";
 25→  int _cursorPosition;
 26→  int _selectionLength;
 27→  bool _isBold;
 28→  bool _isItalic;
 29→  bool _isUnderline;
 30→  bool _isRemoteUpdate;
 31→  bool _disposed;
 32→
 33→  public EditorViewModel(
 34→    RepoService? repoService = null,
 35→    ILoggerFactory? loggerFactory = null,
 36→    Action<Action>? dispatcher = null)
 37→  {
 38→    _repoService = repoService;
 39→    _logger = (loggerFactory ?? NullLoggerFactory.Instance).CreateLogger<EditorViewModel>();
 40→    _dispatcher = dispatcher ?? (action => action());
 41→
 42→    SaveCommand = ReactiveCommand.Create(SaveDocument);
 43→    ExportJsonCommand = ReactiveCommand.Create(ExportJson);
 44→    ToggleBoldCommand = ReactiveCommand.Create(ToggleBold);
 45→    ToggleItalicCommand = ReactiveCommand.Create(ToggleItalic);
 46→    ToggleUnderlineCommand = ReactiveCommand.Create(ToggleUnderline);
 47→  }
 48→
 49→  /// <summary>
 50→  /// The current text content of the local Automerge document.
 51→  /// Two-way bound to the TextBox in the view.
 52→  /// </summary>
 53→  public string DocumentText
 54→  {
 55→    get => _documentText;
 56→    set
 57→    {
 58→      if(_documentText == value)
 59→      {
 60→        return;
 61→      }
 62→
 63→      if(_automergeService is not null && !_isRemoteUpdate)
 64→      {
 65→        ApplyTextChange(value);
 66→      }
 67→
 68→      this.RaiseAndSetIfChanged(ref _documentText, value);
 69→    }
 70→  }
 71→
 72→  /// <summary>
 73→  /// Current sync status description.
 74→  /// </summary>
 75→  public string SyncStatus
 76→  {
 77→    get => _syncStatus;
 78→    set => this.RaiseAndSetIfChanged(ref _syncStatus, value);
 79→  }
 80→
 81→  /// <summary>
 82→  /// Current cursor position in the local document.
 83→  /// </summary>
 84→  public int CursorPosition
 85→  {
 86→    get => _cursorPosition;
 87→    set
 88→    {
 89→      this.RaiseAndSetIfChanged(ref _cursorPosition, value);
 90→      UpdateFormattingState();
 91→    }
 92→  }
 93→
 94→  /// <summary>
 95→  /// Length of the current text selection.
 96→  /// </summary>
 97→  public int SelectionLength
 98→  {
 99→    get => _selectionLength;
100→    set => this.RaiseAndSetIfChanged(ref _selectionLength, value);
101→  }
102→
103→  /// <summary>
104→  /// Whether bold formatting is active at the cursor.
105→  /// </summary>
106→  public bool IsBold
107→  {
108→    get => _isBold;
109→    set => this.RaiseAndSetIfChanged(ref _isBold, value);
110→  }
111→
112→  /// <summary>
113→  /// Whether italic formatting is active at the cursor.
114→  /// </summary>
115→  public bool IsItalic
116→  {
117→    get => _isItalic;
118→    set => this.RaiseAndSetIfChanged(ref _isItalic, value);
119→  }
120→
121→  /// <summary>
122→  /// Whether underline formatting is active at the cursor.
123→  /// </summary>
124→  public bool IsUnderline
125→  {
126→    get => _isUnderline;
127→    set => this.RaiseAndSetIfChanged(ref _isUnderline, value);
128→  }
129→
130→  /// <summary>
131→  /// Gets the RepoService for document operations.
132→  /// </summary>
133→  internal RepoService? RepoService => _repoService;
134→
135→  /// <summary>
136→  /// Gets the AutomergeService for rich text CRDT operations.
137→  /// </summary>
138→  internal AutomergeService? AutomergeService => _automergeService;
139→
140→  /// <summary>
141→  /// Gets or sets the DocHandle for collaborative sync. Set by EditorWindow after document creation/join.
142→  /// </summary>
143→  internal DocHandle<object>? DocHandle
144→  {
145→    get => _docHandle;
146→    set
147→    {
148→      if(_docHandle is not null)
149→      {
150→        _docHandle.Changed -= OnDocHandleChanged;
151→      }
152→
153→      _docHandle = value;
154→
155→      if(_docHandle is not null)
156→      {
157→        _docHandle.Changed += OnDocHandleChanged;
158→      }
159→    }
160→  }
161→
162→  public ReactiveCommand<Unit, Unit> SaveCommand { get; }
163→
164→  public ReactiveCommand<Unit, Unit> ExportJsonCommand { get; }
165→
166→  public ReactiveCommand<Unit, Unit> ToggleBoldCommand { get; }
167→
168→  public ReactiveCommand<Unit, Unit> ToggleItalicCommand { get; }
169→
170→  public ReactiveCommand<Unit, Unit> ToggleUnderlineCommand { get; }
171→
172→  /// <summary>
173→  /// Sets the AutomergeService for text operations (after document is created/loaded).
174→  /// </summary>
175→  internal void SetAutomergeService(AutomergeService service)
176→  {
177→    _automergeService = service;
178→    RefreshFromDocument();
179→  }
180→
181→  internal void ApplyTextChange(string newText)
182→  {
183→    if(_automergeService is null || _docHandle is null)
184→    {
185→      return;
186→    }
187→
188→    string currentText = _automergeService.GetText();
189→
190→    // Find the difference and apply as a splice operation.
191→    // This is a simplified diff: find common prefix and suffix.
192→    int prefixLen = 0;
193→    int minLen = Math.Min(currentText.Length, newText.Length);
194→    while(prefixLen < minLen && currentText[prefixLen] == newText[prefixLen])
195→    {
196→      prefixLen++;
197→    }
198→
199→    int suffixLen = 0;
200→    int maxSuffix = minLen - prefixLen;
201→    while(suffixLen < maxSuffix
202→      && currentText[currentText.Length - 1 - suffixLen] == newText[newText.Length - 1 - suffixLen])
203→    {
204→      suffixLen++;
205→    }
206→
207→    int deleteCount = currentText.Length - prefixLen - suffixLen;
208→    string insertText = newText.Substring(prefixLen, newText.Length - prefixLen - suffixLen);
209→
210→    if(deleteCount > 0 || insertText.Length > 0)
211→    {
212→      SaveCursorBeforeEdit();
213→      var textId = _automergeService.TextId;
214→      _docHandle.Change(
215→        doc => doc.SpliceText(textId, (ulong)prefixLen, deleteCount, insertText),
216→        $"Edit at {prefixLen}");
217→    }
218→  }
219→
220→  internal void RefreshFromDocument()
221→  {
222→    if(_automergeService is null)
223→    {
224→      return;
225→    }
226→
227→    string text = _automergeService.GetText();
228→    if(_documentText != text)
229→    {
230→      _isRemoteUpdate = true;
231→      try
232→      {
233→        _documentText = text;
234→        this.RaisePropertyChanged(nameof(DocumentText));
235→      }
236→      finally
237→      {
238→        _isRemoteUpdate = false;
239→      }
240→    }
241→
242→    UpdateFormattingState();
243→  }
244→
245→  void OnDocHandleChanged(object? sender, DocHandleChangeEventArgs<object> e)
246→  {
247→    if(e.IsLocal)
248→    {
249→      return;
250→    }
251→
252→    _dispatcher(() =>
253→    {
254→      SaveCursorBeforeEdit();
255→      RefreshFromDocument();
256→      RestoreCursorAfterEdit();
257→    });
258→  }
259→
260→  void SaveCursorBeforeEdit()
261→  {
262→    if(_automergeService is null || _cursorPosition <= 0)
263→    {
264→      _savedCursor = null;
265→      return;
266→    }
267→
268→    try
269→    {
270→      ulong pos = (ulong)Math.Min(_cursorPosition, _automergeService.GetText().Length);
271→      if(pos > 0)
272→      {
273→        _savedCursor = _automergeService.GetCursor(pos - 1);
274→      }
275→      else
276→      {
277→        _savedCursor = null;
278→      }
279→    }
280→    catch(Exception)
281→    {
282→      _savedCursor = null;
283→    }
284→  }
285→
286→  void RestoreCursorAfterEdit()
287→  {
288→    if(_automergeService is null || _savedCursor is null)
289→    {
290→      return;
291→    }
292→
293→    try
294→    {
295→      ulong pos = _automergeService.GetCursorPosition(_savedCursor);
296→      CursorPosition = (int)(pos + 1);
297→    }
298→    catch(Exception)
299→    {
300→      // Cursor may be invalid after merge — leave at current position
301→    }
302→
303→    _savedCursor = null;
304→  }
305→
306→  void ToggleBold()
307→  {
308→    if(_automergeService is null || _docHandle is null || _selectionLength <= 0)
309→    {
310→      return;
311→    }
312→
313→    ulong start = (ulong)_cursorPosition;
314→    ulong end = (ulong)(_cursorPosition + _selectionLength);
315→    var textId = _automergeService.TextId;
316→
317→    if(_isBold)
318→    {
319→      _docHandle.Change(doc => doc.Unmark(textId, "bold", start, end, ExpandMode.Both), "Unmark bold");
320→    }
321→    else
322→    {
323→      _docHandle.Change(doc => doc.Mark(textId, start, end, "bold", true, ExpandMode.Both), "Mark bold");
324→    }
325→
326→    UpdateFormattingState();
327→  }
328→
329→  void ToggleItalic()
330→  {
331→    if(_automergeService is null || _docHandle is null || _selectionLength <= 0)
332→    {
333→      return;
334→    }
335→
336→    ulong start = (ulong)_cursorPosition;
337→    ulong end = (ulong)(_cursorPosition + _selectionLength);
338→    var textId = _automergeService.TextId;
339→
340→    if(_isItalic)
341→    {
342→      _docHandle.Change(doc => doc.Unmark(textId, "italic", start, end, ExpandMode.Both), "Unmark italic");
343→    }
344→    else
345→    {
346→      _docHandle.Change(doc => doc.Mark(textId, start, end, "italic", true, ExpandMode.Both), "Mark italic");
347→    }
348→
349→    UpdateFormattingState();
350→  }
351→
352→  void ToggleUnderline()
353→  {
354→    if(_automergeService is null || _docHandle is null || _selectionLength <= 0)
355→    {
356→      return;
357→    }
358→
359→    ulong start = (ulong)_cursorPosition;
360→    ulong end = (ulong)(_cursorPosition + _selectionLength);
361→    var textId = _automergeService.TextId;
362→
363→    if(_isUnderline)
364→    {
365→      _docHandle.Change(doc => doc.Unmark(textId, "underline", start, end, ExpandMode.Both), "Unmark underline");
366→    }
367→    else
368→    {
369→      _docHandle.Change(doc => doc.Mark(textId, start, end, "underline", true, ExpandMode.Both), "Mark underline");
370→    }
371→
372→    UpdateFormattingState();
373→  }
374→
375→  void UpdateFormattingState()
376→  {
377→    if(_disposed || _automergeService is null)
378→    {
379→      return;
380→    }
381→
382→    var marks = _automergeService.GetMarks();
383→    FormattingState state = FormattingState.FromMarks(marks, (ulong)_cursorPosition);
384→    IsBold = state.IsBold;
385→    IsItalic = state.IsItalic;
386→    IsUnderline = state.IsUnderline;
387→  }
388→
389→  void SaveDocument()
390→  {
391→    if(_automergeService is null)
392→    {
393→      SyncStatus = "No document loaded";
394→      return;
395→    }
396→
397→    byte[] saved = _automergeService.Save();
398→    SyncStatus = $"Saved ({saved.Length} bytes)";
399→  }
400→
401→  void ExportJson()
402→  {
403→    if(_automergeService is null)
404→    {
405→      SyncStatus = "No document loaded";
406→      return;
407→    }
408→
409→    string json = _automergeService.Document.HydrateJson();
410→    _logger.LogInformation("Document JSON: {Json}", json);
411→    SyncStatus = $"Exported JSON ({json.Length} chars)";
412→  }
413→
414→  public void Dispose()
415→  {
416→    if(!_disposed)
417→    {
418→      _disposed = true;
419→
420→      if(_docHandle is not null)
421→      {
422→        _docHandle.Changed -= OnDocHandleChanged;
423→      }
424→
425→      _automergeService?.Dispose();
426→      _repoService?.Dispose();
427→    }
428→  }
429→}
