  3→using Six.Automerge;
  4→
  5→namespace DemoApp.CollaborativeEditor.Services;
  6→
  7→/// <summary>
  8→/// Wraps <see cref="AutomergeDocument"/> to provide rich text CRDT operations
  9→/// for the collaborative rich text editor demo. Supports text editing, inline
 10→/// marks (bold, italic, underline, link), and block-level structure (paragraphs).
 11→/// </summary>
 12→sealed class AutomergeService : IDisposable
 13→{
 14→  readonly AutomergeDocument _document;
 15→  readonly AutomergeObjectId _textId;
 16→  readonly bool _ownsDocument;
 17→  bool _disposed;
 18→
 19→  public AutomergeService()
 20→  {
 21→    _document = AutomergeDocument.Create();
 22→    _textId = _document.PutObject(_document.RootId, "content", AutomergeContainerType.Text);
 23→    _document.Commit("Initialize text field");
 24→    _ownsDocument = true;
 25→  }
 26→
 27→  AutomergeService(AutomergeDocument document, AutomergeObjectId textId, bool ownsDocument)
 28→  {
 29→    _document = document;
 30→    _textId = textId;
 31→    _ownsDocument = ownsDocument;
 32→  }
 33→
 34→  /// <summary>
 35→  /// Gets the underlying document for sync operations.
 36→  /// </summary>
 37→  public AutomergeDocument Document => _document;
 38→
 39→  /// <summary>
 40→  /// Gets the text object identifier for direct access.
 41→  /// </summary>
 42→  public AutomergeObjectId TextId => _textId;
 43→
 44→  /// <summary>
 45→  /// Gets the current text content of the document.
 46→  /// </summary>
 47→  public string GetText()
 48→  {
 49→    ThrowIfDisposed();
 50→    return _document.GetText(_textId);
 51→  }
 52→
 53→  /// <summary>
 54→  /// Splices text at the given position: deletes <paramref name="deleteCount"/> characters
 55→  /// and inserts <paramref name="insertText"/> at <paramref name="index"/>.
 56→  /// </summary>
 57→  public void SpliceText(ulong index, long deleteCount, string insertText)
 58→  {
 59→    ThrowIfDisposed();
 60→    _document.SpliceText(_textId, index, deleteCount, insertText);
 61→    _document.Commit($"Edit at {index}");
 62→  }
 63→
 64→  /// <summary>
 65→  /// Applies or removes a bold mark on the specified range.
 66→  /// </summary>
 67→  public void MarkBold(ulong start, ulong end, bool value)
 68→  {
 69→    ThrowIfDisposed();
 70→    _document.Mark(_textId, start, end, "bold", value, ExpandMode.Both);
 71→    _document.Commit("Mark bold");
 72→  }
 73→
 74→  /// <summary>
 75→  /// Removes the bold mark from the specified range.
 76→  /// </summary>
 77→  public void UnmarkBold(ulong start, ulong end)
 78→  {
 79→    ThrowIfDisposed();
 80→    _document.Unmark(_textId, "bold", start, end, ExpandMode.Both);
 81→    _document.Commit("Unmark bold");
 82→  }
 83→
 84→  /// <summary>
 85→  /// Applies or removes an italic mark on the specified range.
 86→  /// </summary>
 87→  public void MarkItalic(ulong start, ulong end, bool value)
 88→  {
 89→    ThrowIfDisposed();
 90→    _document.Mark(_textId, start, end, "italic", value, ExpandMode.Both);
 91→    _document.Commit("Mark italic");
 92→  }
 93→
 94→  /// <summary>
 95→  /// Removes the italic mark from the specified range.
 96→  /// </summary>
 97→  public void UnmarkItalic(ulong start, ulong end)
 98→  {
 99→    ThrowIfDisposed();
100→    _document.Unmark(_textId, "italic", start, end, ExpandMode.Both);
101→    _document.Commit("Unmark italic");
102→  }
103→
104→  /// <summary>
105→  /// Applies or removes an underline mark on the specified range.
106→  /// </summary>
107→  public void MarkUnderline(ulong start, ulong end, bool value)
108→  {
109→    ThrowIfDisposed();
110→    _document.Mark(_textId, start, end, "underline", value, ExpandMode.Both);
111→    _document.Commit("Mark underline");
112→  }
113→
114→  /// <summary>
115→  /// Removes the underline mark from the specified range.
116→  /// </summary>
117→  public void UnmarkUnderline(ulong start, ulong end)
118→  {
119→    ThrowIfDisposed();
120→    _document.Unmark(_textId, "underline", start, end, ExpandMode.Both);
121→    _document.Commit("Unmark underline");
122→  }
123→
124→  /// <summary>
125→  /// Applies a link mark with the specified URL on the given range.
126→  /// </summary>
127→  public void MarkLink(ulong start, ulong end, string url)
128→  {
129→    ThrowIfDisposed();
130→    _document.Mark(_textId, start, end, "link", url, ExpandMode.None);
131→    _document.Commit("Mark link");
132→  }
133→
134→  /// <summary>
135→  /// Removes the link mark from the specified range.
136→  /// </summary>
137→  public void UnmarkLink(ulong start, ulong end)
138→  {
139→    ThrowIfDisposed();
140→    _document.Unmark(_textId, "link", start, end, ExpandMode.None);
141→    _document.Commit("Unmark link");
142→  }
143→
144→  /// <summary>
145→  /// Gets all marks applied to the text.
146→  /// </summary>
147→  public IReadOnlyList<AutomergeMarkInfo> GetMarks()
148→  {
149→    ThrowIfDisposed();
150→    return _document.GetMarks(_textId);
151→  }
152→
153→  /// <summary>
154→  /// Gets the text content segmented by marks and blocks.
155→  /// </summary>
156→  public IReadOnlyList<AutomergeSpan> GetSpans()
157→  {
158→    ThrowIfDisposed();
159→    return _document.GetSpans(_textId);
160→  }
161→
162→  /// <summary>
163→  /// Inserts a block marker at the given index, splitting the text.
164→  /// Sets the block type to <paramref name="blockType"/>.
165→  /// </summary>
166→  public void SplitBlock(ulong index, string blockType)
167→  {
168→    ThrowIfDisposed();
169→    AutomergeObjectId blockId = _document.SplitBlock(_textId, index);
170→    _document.PutString(blockId, "type", blockType);
171→    _document.Commit($"Split block at {index}");
172→  }
173→
174→  /// <summary>
175→  /// Removes a block marker at the given index, joining adjacent text.
176→  /// </summary>
177→  public void JoinBlock(ulong index)
178→  {
179→    ThrowIfDisposed();
180→    _document.JoinBlock(_textId, index);
181→    _document.Commit($"Join block at {index}");
182→  }
183→
184→  /// <summary>
185→  /// Atomically updates the span list with minimal diff.
186→  /// </summary>
187→  public void UpdateSpans(IReadOnlyList<AutomergeSpan> spans)
188→  {
189→    ThrowIfDisposed();
190→    _document.UpdateSpans(_textId, spans);
191→    _document.Commit("Update spans");
192→  }
193→
194→  /// <summary>
195→  /// Gets a stable cursor at the given index.
196→  /// </summary>
197→  public AutomergeCursor GetCursor(ulong index)
198→  {
199→    ThrowIfDisposed();
200→    return _document.GetCursor(_textId, index);
201→  }
202→
203→  /// <summary>
204→  /// Resolves a cursor to its current index position.
205→  /// </summary>
206→  public ulong GetCursorPosition(AutomergeCursor cursor)
207→  {
208→    ThrowIfDisposed();
209→    return _document.GetCursorPosition(_textId, cursor);
210→  }
211→
212→  /// <summary>
213→  /// Saves the full document state as a byte array.
214→  /// </summary>
215→  public byte[] Save()
216→  {
217→    ThrowIfDisposed();
218→    return _document.Save();
219→  }
220→
221→  /// <summary>
222→  /// Creates an AutomergeService that wraps an existing document, initializing the text field
223→  /// if it doesn't already exist. The document is NOT owned (not disposed by this service).
224→  /// </summary>
225→  public static AutomergeService FromDocument(AutomergeDocument document)
226→  {
227→    ArgumentNullException.ThrowIfNull(document);
228→
229→    var keys = document.GetKeys(document.RootId).ToList();
230→    AutomergeObjectId textId;
231→
232→    if(keys.Contains("content"))
233→    {
234→      textId = document.GetObject(document.RootId, "content")
235→        ?? throw new InvalidOperationException("Could not resolve 'content' text object.");
236→    }
237→    else
238→    {
239→      textId = document.PutObject(document.RootId, "content", AutomergeContainerType.Text);
240→      document.Commit("Initialize text field");
241→    }
242→
243→    return new AutomergeService(document, textId, ownsDocument: false);
244→  }
245→
246→  /// <summary>
247→  /// Loads a document from a previously saved byte array.
248→  /// </summary>
249→  public static AutomergeService Load(byte[] data)
250→  {
251→    AutomergeDocument doc = AutomergeDocument.Load(data);
252→    List<string> keys = doc.GetKeys(doc.RootId).ToList();
253→    if(!keys.Contains("content"))
254→    {
255→      throw new InvalidOperationException("Saved document does not contain a 'content' text field.");
256→    }
257→
258→    AutomergeObjectId textId = doc.GetObject(doc.RootId, "content")
259→      ?? throw new InvalidOperationException("Could not resolve 'content' text object.");
260→
261→    return new AutomergeService(doc, textId, ownsDocument: true);
262→  }
263→
264→  public void Dispose()
265→  {
266→    if(!_disposed)
267→    {
268→      _disposed = true;
269→      if(_ownsDocument)
270→      {
271→        _document.Dispose();
272→      }
273→    }
274→  }
275→
276→  void ThrowIfDisposed()
277→  {
278→    ObjectDisposedException.ThrowIf(_disposed, this);
279→  }
280→}
