185→  /// <summary>
186→  /// Scans the storage directory for previously stored documents.
187→  /// Uses the FileSystemStorageAdapter's sharded directory structure.
188→  /// </summary>
189→  /// <param name="storageDirectory">The base storage directory to scan.</param>
190→  public void LoadStoredDocuments(string storageDirectory)
191→  {
192→    StoredDocuments.Clear();
193→
194→    if(!Directory.Exists(storageDirectory))
195→    {
196→      return;
197→    }
198→
199→    // FileSystemStorageAdapter sharding: first 2 chars are the shard dir,
200→    // remaining chars are the subdirectory name.
201→    // Reconstruct document IDs by combining shard prefix + subdirectory name.
202→    foreach(string shardDir in Directory.GetDirectories(storageDirectory))
203→    {
204→      string shardName = Path.GetFileName(shardDir);
205→      if(shardName.Length != 2)
206→      {
207→        continue;
208→      }
209→
210→      foreach(string docDir in Directory.GetDirectories(shardDir))
211→      {
212→        string docSuffix = Path.GetFileName(docDir);
213→        string documentId = shardName + docSuffix;
214→        StoredDocuments.Add(documentId);
215→      }
216→    }
217→
218→    RefreshAllDocuments();
219→  }
220→
221→  /// <summary>
222→  /// Loads document IDs from the server via the <see cref="RepoService"/> and merges them
223→  /// with local documents. Handles connection failures gracefully by showing only local documents.
224→  /// </summary>
225→  /// <param name="repoService">The repo service to query. If null or not connected, only local documents are shown.</param>
226→  public async Task LoadServerDocumentsAsync(RepoService? repoService)
227→  {
228→    IsLoadingServerDocuments = true;
229→
230→    try
231→    {
232→      ServerDocuments.Clear();
233→
234→      if(repoService is null || repoService.ConnectionState != ConnectionState.Connected)
235→      {
236→        RefreshAllDocuments();
237→        return;
238→      }
239→
240→      try
241→      {
242→        List<string> serverDocs = await repoService.ListServerDocumentsAsync();
243→        foreach(string docId in serverDocs)
244→        {
245→          ServerDocuments.Add(docId);
246→        }
247→      }
248→      catch(Exception)
249→      {
250→        // Connection failure — show only local documents
251→        ServerDocuments.Clear();
252→      }
253→
254→      RefreshAllDocuments();
255→    }
256→    finally
257→    {
258→      IsLoadingServerDocuments = false;
259→    }
260→  }
261→
262→  /// <summary>
263→  /// Rebuilds the <see cref="AllDocuments"/> collection by merging
264→  /// <see cref="StoredDocuments"/> and <see cref="ServerDocuments"/>.
265→  /// </summary>
266→  public void RefreshAllDocuments()
267→  {
268→    AllDocuments.Clear();
269→
270→    HashSet<string> localSet = new(StoredDocuments, StringComparer.Ordinal);
271→    HashSet<string> serverSet = new(ServerDocuments, StringComparer.Ordinal);
272→    HashSet<string> seen = new(StringComparer.Ordinal);
273→
274→    // Add local documents first
275→    foreach(string docId in StoredDocuments)
276→    {
277→      if(!seen.Add(docId))
278→      {
279→        continue;
280→      }
281→
282→      DocumentSource source = serverSet.Contains(docId) ? DocumentSource.Both : DocumentSource.Local;
283→      AllDocuments.Add(new DocumentEntry(docId, source));
284→    }
285→
286→    // Add server-only documents
287→    foreach(string docId in ServerDocuments)
288→    {
289→      if(!seen.Add(docId))
290→      {
291→        continue;
292→      }
293→
294→      AllDocuments.Add(new DocumentEntry(docId, DocumentSource.Server));
295→    }
296→
297→    OnPropertyChanged(nameof(AllDocuments));
298→  }
299→
300→  void OnPropertyChanged([CallerMemberName] string? propertyName = null)
301→  {
302→    PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
303→  }
304→}
