  1→using System.Buffers.Binary;
  2→using System.Text;
  3→using Six.Automerge.FFI;
  4→using Native = Six.Automerge.FFI.Native;
  5→
  6→namespace Six.Automerge;
  7→
  8→[PublicAPI]
  9→public sealed class AutomergeDocument : IDisposable
 10→{
 11→  readonly Native.AutomergeDoc _doc;
 12→  bool _disposed;
 13→  static readonly UTF8Encoding ActorIdEncoding = new(false, true);
 14→
 15→  AutomergeDocument(Native.AutomergeDoc doc)
 16→  {
 17→    _doc = doc;
 18→  }
 19→
 20→  void ThrowIfDisposed()
 21→  {
 22→    if(_disposed)
 23→    {
 24→      throw new ObjectDisposedException(nameof(AutomergeDocument));
 25→    }
 26→  }
 27→
 28→  public static AutomergeDocument Create(string? actorId = null)
 29→  {
 30→    if(string.IsNullOrWhiteSpace(actorId))
 31→    {
 32→      using var none = Native.OptionUtf8String.None;
 33→      return CreateDocument(none, false, null);
 34→    }
 35→
 36→    if(IsHexActorId(actorId))
 37→    {
 38→      using var actorOption = CreateActorHexOption(actorId);
 39→      return CreateDocument(actorOption, true, actorId);
 40→    }
 41→
 42→    using var defaultOption = Native.OptionUtf8String.None;
 43→    var document = CreateDocument(defaultOption, false, null);
 44→    document.ActorId = actorId;
 45→    return document;
 46→  }
 47→
 48→  static AutomergeDocument CreateDocument(
 49→    Native.OptionUtf8String actorOption,
 50→    bool actorProvided,
 51→    string? requestedActorId)
 52→  {
 53→    try
 54→    {
 55→      var native = Native.AutomergeDoc.New(actorOption);
 56→      return new AutomergeDocument(native);
 57→    }
 58→    catch(Native.InteropException ex)
 59→    {
 60→      var code = actorProvided
 61→        ? Native.AutomergeFfiErrorCode.InvalidActorId
 62→        : Native.AutomergeFfiErrorCode.AutomergeError;
 63→
 64→      var message = actorProvided
 65→        ? $"Invalid actor id '{requestedActorId}'. Provide a valid hex identifier or use a non-hex string to let the library derive one."
 66→        : "Failed to create Automerge document.";
 67→
 68→      throw new AutomergeException(code, message, ex);
 69→    }
 70→  }
 71→
 72→  static Native.OptionUtf8String CreateActorHexOption(string actorId)
 73→  {
 74→    var utf8 = Native.Utf8String.From(actorId);
 75→    return Native.OptionUtf8String.Some(utf8);
 76→  }
 77→
 78→  static bool IsHexActorId(string value)
 79→  {
 80→    if(value.Length == 0 || (value.Length % 2) != 0)
 81→    {
 82→      return false;
 83→    }
 84→
 85→    foreach(var ch in value)
 86→    {
 87→      if(!Uri.IsHexDigit(ch))
 88→      {
 89→        return false;
 90→      }
 91→    }
 92→
 93→    return true;
 94→  }
 95→
 96→  static bool TryDecodeActorId(string hex, out string decoded)
 97→  {
 98→    decoded = string.Empty;
 99→    if(!IsHexActorId(hex))
100→    {
101→      return false;
102→    }
103→
104→    try
105→    {
106→      var bytes = Convert.FromHexString(hex);
107→      if(bytes.Length == 0)
108→      {
109→        return false;
110→      }
111→
112→      var candidate = ActorIdEncoding.GetString(bytes);
113→      if(!IsPrintableActorId(candidate))
114→      {
115→        return false;
116→      }
117→
118→      var roundtrip = Convert.ToHexString(ActorIdEncoding.GetBytes(candidate));
119→      if(!roundtrip.Equals(hex, StringComparison.OrdinalIgnoreCase))
120→      {
121→        return false;
122→      }
123→
124→      decoded = candidate;
125→      return true;
126→    }
127→    catch(FormatException)
128→    {
129→      return false;
130→    }
131→    catch(DecoderFallbackException)
132→    {
133→      return false;
134→    }
135→    catch(EncoderFallbackException)
136→    {
137→      return false;
138→    }
139→  }
140→
141→  static bool IsPrintableActorId(string value)
142→  {
143→    foreach(var ch in value)
144→    {
145→      if(char.IsControl(ch))
146→      {
147→        return false;
148→      }
149→    }
