 110→  /// <summary>
 111→  /// Initializes a new repository with the specified configuration.
 112→  /// </summary>
 113→  /// <param name="config">Configuration for the repository.</param>
 114→  /// <exception cref="ArgumentNullException">Thrown if config is null.</exception>
 115→  public Repo(RepoConfig config)
 116→  {
 117→    if(config is null)
 118→      throw new ArgumentNullException(nameof(config));
 119→
 120→    // Initialize identity
 121→    _peerId = config.PeerId ?? PeerId.Generate();
 122→    _isEphemeral = config.IsEphemeral;
 123→    _saveDebounceRate = config.SaveDebounceRate;
 124→    _shareConfig = config.ShareConfig ?? ShareConfig.AllowAll;
 125→    _idFactory = config.IdFactory;
 126→
 127→    // Initialize storage subsystem
 128→    if(config.Storage is not null)
 129→    {
 130→      _storage = new StorageSubsystem(config.Storage);
 131→      _storage.DocumentLoaded += OnStorageDocumentLoaded;
 132→      _storage.DocumentSaved += OnStorageDocumentSaved;
 133→    }
 134→
 135→    // Initialize network subsystem
 136→    _network = new NetworkSubsystem(config.NetworkAdapters);
 137→    _network.PeerCandidate += OnNetworkPeerCandidate;
 138→    _network.PeerDisconnected += OnNetworkPeerDisconnected;
 139→    _network.MessageReceived += OnNetworkMessageReceived;
 140→
 141→    // Initialize synchronizer
 142→    _synchronizer = new CollectionSynchronizer(
 143→      GetDocument,
 144→      UpdateDocument,
 145→      GetPeerMetadata,
 146→      RequestDocument,
 147→      GetDocumentLock,
 148→      config.Denylist);
 149→
 150→    _synchronizer.MessageToSend += OnSynchronizerMessage;
 151→    _synchronizer.SyncStateChanged += OnSynchronizerSyncStateChanged;
 152→    _synchronizer.DocumentUnavailable += OnSynchronizerDocumentUnavailable;
 153→
 154→    // Set share and access policies
 155→    if(_shareConfig.Announce is not null)
 156→    {
 157→      _synchronizer.SetSharePolicy(AdaptAnnouncePolicy);
 158→    }
 159→
 160→    if(_shareConfig.Access is not null)
 161→    {
 162→      _synchronizer.SetAccessPolicy(AdaptAccessPolicy);
 163→    }
 164→  }
