 306→  /// <summary>
 307→  /// Creates a new document asynchronously with optional initial value.
 308→  /// Uses idFactory for document ID generation if configured.
 309→  /// This mirrors TypeScript's experimental Repo.create2() method.
 310→  /// </summary>
 311→  /// <typeparam name="T">The document content type.</typeparam>
 312→  /// <param name="initialValue">Optional initial value for the document.</param>
 313→  /// <returns>A task that resolves to a handle to the newly created document.</returns>
 314→  public async Task<DocHandle<T>> CreateAsync<T>(T? initialValue = default)
 315→  {
 316→    ThrowIfDisposed();
 317→
 318→    // Generate document ID
 319→    DocumentId documentId;
 320→    if(_idFactory is not null)
 321→    {
 322→      // Use idFactory for ID generation
 323→      var initialDoc = AutomergeDocument.Create();
 324→      var heads = initialDoc.GetHeads();
 325→      var binaryId = await _idFactory(heads).ConfigureAwait(false);
 326→      documentId = DocumentId.FromBinary(binaryId);
 327→    }
 328→    else
 329→    {
 330→      // Fall back to default ID generation
 331→      documentId = DocumentId.Generate();
 332→    }
 333→
 334→    // Validate document ID
 335→    if(!DocumentId.IsValid(documentId))
 336→    {
 337→      throw new ArgumentException($"Invalid document ID: {documentId}");
 338→    }
 339→
 340→    DocHandle<T> handle;
 341→
 342→    await _handleLock.WaitAsync().ConfigureAwait(false);
 343→    try
 344→    {
 345→      // Check if already exists
 346→      if(_handleCache.ContainsKey(documentId))
 347→      {
 348→        throw new InvalidOperationException($"Document already exists: {documentId}");
 349→      }
 350→
 351→      // Create document
 352→      var doc = AutomergeDocument.Create();
 353→
 354→      // Create handle
 355→      handle = new DocHandle<T>(
 356→        documentId,
 357→        new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 358→        doc);
 359→
 360→      // Cache handle
 361→      _handleCache[documentId] = handle;
 362→    }
 363→    finally
 364→    {
 365→      _handleLock.Release();
 366→    }
 367→
 368→    // Register outside the lock to prevent deadlocks
 369→    await RegisterHandle(documentId, handle).ConfigureAwait(false);
 370→
 371→    // Emit event
 372→    DocumentLoaded?.Invoke(this,
 373→      new DocumentEventArgs { DocumentId = documentId, Handle = handle });
 374→
 375→    return handle;
 376→  }
