 444→  /// <summary>
 445→  /// Finds an existing document, loading from storage or requesting from network.
 446→  /// </summary>
 447→  /// <typeparam name="T">The document content type.</typeparam>
 448→  /// <param name="documentId">The document ID to find.</param>
 449→  /// <param name="timeout">Optional timeout for loading. Default: 10 seconds.</param>
 450→  /// <returns>
 451→  /// A <see cref="DocHandle{T}"/> if the document exists or was loaded successfully, or null if the document
 452→  /// does not exist and could not be loaded from the network within the timeout period.
 453→  /// </returns>
 454→  /// <exception cref="ArgumentException">Thrown if document ID is invalid.</exception>
 455→  public async Task<DocHandle<T>?> Find<T>(string documentId, TimeSpan? timeout = null)
 456→  {
 457→    if(string.IsNullOrWhiteSpace(documentId))
 458→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 459→
 460→    if(!DocumentId.IsValid(documentId))
 461→      throw new ArgumentException($"Invalid document ID: {documentId}", nameof(documentId));
 462→
 463→    var documentIdValue = DocumentId.Parse(documentId);
 464→
 465→    ThrowIfDisposed();
 466→
 467→    timeout ??= TimeSpan.FromSeconds(10);
 468→
 469→    await _handleLock.WaitAsync().ConfigureAwait(false);
 470→    Task<IDocHandle>? findTask;
 471→    try
 472→    {
 473→      // Check cache first
 474→      if(_handleCache.TryGetValue(documentId, out var cachedHandle))
 475→      {
 476→        return (DocHandle<T>)cachedHandle;
 477→      }
 478→
 479→      // Check if find already in progress
 480→      if(_findInProgress.TryGetValue(documentId, out findTask))
 481→      {
 482→        // Wait for existing find operation
 483→        _handleLock.Release();
 484→        var result = await findTask.ConfigureAwait(false);
 485→        return (DocHandle<T>)result;
 486→      }
 487→
 488→      // Start new find operation
 489→      var tcs = new TaskCompletionSource<IDocHandle>();
 490→      _findInProgress[documentId] = tcs.Task;
 491→      findTask = tcs.Task;
 492→    }
 493→    finally
 494→    {
 495→      if(_handleLock.CurrentCount == 0)
 496→        _handleLock.Release();
 497→    }
 498→
 499→    try
 500→    {
 501→      // Attempt to load from storage first
 502→      AutomergeDocument? doc = null;
 503→      if(_storage is not null)
 504→      {
 505→        doc = await _storage.LoadDoc(documentId).ConfigureAwait(false);
 506→      }
 507→
 508→      // Create handle (without document - we'll initialize explicitly)
 509→      var handle = new DocHandle<T>(
 510→        documentId,
 511→        new DocHandleOptions<T> { IsNew = false, ViewFactory = CreateViewFactory<T>(), Timeout = timeout.Value },
 512→        document: null);
 513→
 514→      // Cache handle
 515→      await _handleLock.WaitAsync().ConfigureAwait(false);
 516→      try
 517→      {
 518→        _handleCache[documentId] = handle;
 519→        _findInProgress.Remove(documentId);
 520→
 521→        // Complete the TaskCompletionSource
 522→        if(findTask is Task<IDocHandle> task &&
 523→           task.AsyncState is TaskCompletionSource<IDocHandle> taskSource)
 524→        {
 525→          taskSource.SetResult(handle);
 526→        }
 527→      }
 528→      finally
 529→      {
 530→        _handleLock.Release();
 531→      }
 532→
 533→      // Begin lifecycle: Idle → Loading
 534→      handle.Begin();
 535→
 536→      // Split into two paths based on whether a document was loaded from storage
 537→      if(doc is not null)
 538→      {
 539→        // PATH A: Document found in storage
 540→        // Initialize the handle with the loaded document
 541→        handle.Initialize(doc, isNewDocument: false);
 542→        handle.DoneLoading();  // Loading → Ready
 543→
 544→        // Now register with subsystems
 545→        await RegisterHandle(documentId, handle).ConfigureAwait(false);
 546→
 547→        // Emit loaded event
 548→        DocumentLoaded?.Invoke(this,
 549→          new DocumentEventArgs { DocumentId = documentIdValue, Handle = handle });
 550→
 551→        return handle;  // Already ready, return immediately
 552→      }
 553→      else
 554→      {
 555→        // PATH B: Document must be loaded from network (or created if unavailable)
 556→        // Wait for network to be ready before requesting
 557→        await _network.WhenReady().ConfigureAwait(false);
 558→
 559→        // Transition to requesting state: Loading → Requesting
 560→        handle.Request();
 561→
 562→        // Now register with subsystems (synchronizer sees Requesting state)
 563→        await RegisterHandle(documentId, handle).ConfigureAwait(false);
 564→
 565→        // Wait for the handle to be ready (or timeout)
 566→        using var cts = new CancellationTokenSource(timeout.Value);
 567→        try
 568→        {
 569→          await handle.WhenReadyAsync(cts.Token).ConfigureAwait(false);
 570→          return handle;  // Document loaded successfully from network
 571→        }
 572→        catch(OperationCanceledException)
 573→        {
 574→          // Timeout: document not available from network
 575→          // Return null to indicate document doesn't exist
 576→          // Caller should use Create() to create a new document
 577→          return null;
 578→        }
 579→      }
 580→    }
 581→    catch(Exception)
 582→    {
 583→      // Clean up on error
 584→      await _handleLock.WaitAsync().ConfigureAwait(false);
 585→      try
 586→      {
 587→        _findInProgress.Remove(documentId);
 588→      }
 589→      finally
 590→      {
 591→        _handleLock.Release();
 592→      }
 593→
 594→      throw;
 595→    }
 596→  }
 597→
 598→  #endregion
