 880→  #region Throttled Save
 881→
 882→  /// <summary>
 883→  /// Schedules a throttled save for a document.
 884→  /// </summary>
 885→  async Task ScheduleSave(string documentId)
 886→  {
 887→    if(_storage is null) return;
 888→
 889→    await _saveLock.WaitAsync().ConfigureAwait(false);
 890→    try
 891→    {
 892→      // Cancel existing pending save
 893→      if(_pendingSaves.TryGetValue(documentId, out var existingCts))
 894→      {
 895→        existingCts.Cancel();
 896→        existingCts.Dispose();
 897→      }
 898→
 899→      // Schedule new save after debounce period
 900→      var cts = new CancellationTokenSource();
 901→      _pendingSaves[documentId] = cts;
 902→
 903→      _ = Task.Delay(_saveDebounceRate, cts.Token)
 904→        .ContinueWith(async _ =>
 905→        {
 906→          if(cts.IsCancellationRequested) return;
 907→
 908→          await PerformSave(documentId).ConfigureAwait(false);
 909→
 910→          await _saveLock.WaitAsync().ConfigureAwait(false);
 911→          try
 912→          {
 913→            _pendingSaves.Remove(documentId);
 914→            cts.Dispose();
 915→          }
 916→          finally
 917→          {
 918→            _saveLock.Release();
 919→          }
 920→        }, TaskScheduler.Default);
 921→    }
 922→    finally
 923→    {
 924→      _saveLock.Release();
 925→    }
 926→  }
 927→
 928→  /// <summary>
 929→  /// Performs the actual save operation.
 930→  /// </summary>
 931→  async Task PerformSave(string documentId)
 932→  {
 933→    if(_storage is null) return;
 934→
 935→    await _handleLock.WaitAsync().ConfigureAwait(false);
 936→    IDocHandle? handle;
 937→    try
 938→    {
 939→      if(!_handleCache.TryGetValue(documentId, out handle))
 940→      {
 941→        return; // Document no longer exists
 942→      }
 943→    }
 944→    finally
 945→    {
 946→      _handleLock.Release();
 947→    }
 948→
 949→    var doc = handle.GetDocument();
 950→    if(doc is not null)
 951→    {
 952→      await _storage.SaveDoc(documentId, doc).ConfigureAwait(false);
 953→    }
 954→  }
