 984→  void OnSynchronizerMessage(object? sender, SyncMessageEventArgs e)
 985→  {
 986→    // Stamp our PeerId as sender before forwarding to network.
 987→    // DocSynchronizer creates messages without SenderId (it doesn't know the Repo identity).
 988→    var message = e.Message.SenderId is null
 989→      ? e.Message.WithSender(_peerId)
 990→      : e.Message;
 991→
 992→    // Thread TargetPeerId from the synchronizer so the network layer can route
 993→    // the message to the specific peer instead of broadcasting to all peers.
 994→    if(message.TargetPeerId is null)
 995→    {
 996→      message = message.WithTarget(e.TargetPeerId);
 997→    }
 998→
 999→    _network.Send(message);
