1187→  static Func<AutomergeDocument, T> CreateViewFactory<T>()
1188→  {
1189→    if(typeof(T) == typeof(object) || typeof(T) == typeof(AutomergeDocument))
1190→    {
1191→      return doc => (T)(object)doc;
1192→    }
1193→
