1202→  /// <summary>
1203→  /// Flushes pending saves for specified documents (or all documents).
1204→  /// </summary>
1205→  /// <param name="documentIds">Optional list of document IDs to flush. If null, flushes all.</param>
1206→  public async Task Flush(IEnumerable<string>? documentIds = null)
1207→  {
1208→    if(_storage is null) return;
1209→
1210→    ThrowIfDisposed();
1211→
1212→    var idsToFlush = documentIds?.ToList() ?? _handleCache.Keys.ToList();
1213→
1214→    var saveTasks = new List<Task>();
1215→
1216→    foreach(var documentId in idsToFlush)
1217→    {
1218→      // Cancel pending throttled save
1219→      await _saveLock.WaitAsync().ConfigureAwait(false);
1220→      try
1221→      {
1222→        if(_pendingSaves.TryGetValue(documentId, out var cts))
1223→        {
1224→          cts.Cancel();
1225→          _pendingSaves.Remove(documentId);
1226→        }
1227→      }
1228→      finally
1229→      {
1230→        _saveLock.Release();
1231→      }
1232→
1233→      // Perform immediate save
1234→      saveTasks.Add(PerformSave(documentId));
1235→    }
1236→
1237→    await Task.WhenAll(saveTasks).ConfigureAwait(false);
1238→  }
1239→
1240→  /// <summary>
1241→  /// Removes a document from the cache without deleting from storage.
1242→  /// Useful for memory management.
1243→  /// </summary>
1244→  /// <param name="documentId">The document ID to remove from cache.</param>
1245→  public async Task RemoveFromCache(string documentId)
1246→  {
1247→    if(string.IsNullOrWhiteSpace(documentId))
1248→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
1249→
1250→    ThrowIfDisposed();
1251→
1252→    // Flush first
1253→    await Flush(new[] { documentId }).ConfigureAwait(false);
1254→
1255→    await _handleLock.WaitAsync().ConfigureAwait(false);
1256→    IDocHandle? handle;
1257→    try
1258→    {
1259→      if(!_handleCache.TryGetValue(documentId, out handle))
1260→      {
1261→        return;
1262→      }
1263→
1264→      _handleCache.Remove(documentId);
1265→    }
1266→    finally
1267→    {
1268→      _handleLock.Release();
1269→    }
1270→
1271→    // Unregister from synchronizer
1272→    await _synchronizer.RemoveDocument(documentId).ConfigureAwait(false);
1273→
1274→    // Unload handle
1275→    handle.Unload();
1276→  }
1277→
1278→  /// <summary>
1279→  /// Gracefully shuts down the repository, flushing all pending saves.
1280→  /// </summary>
1281→  public async Task Shutdown()
1282→  {
1283→    if(_isDisposed) return;
1284→
1285→    // Flush all documents
1286→    await Flush().ConfigureAwait(false);
1287→
1288→    // Dispose
1289→    Dispose();
1290→  }
1291→
1292→
1293→  void ThrowIfDisposed()
1294→  {
1295→    if(_isDisposed)
1296→    {
1297→      throw new ObjectDisposedException(nameof(Repo));
1298→    }
1299→  }
