 97→  #region Lifecycle
 98→
 99→  public void Begin()
100→  {
101→    lock(_stateGate)
102→    {
103→      EnsureNotDisposed();
104→      if(_state == HandleState.Idle)
105→      {
106→        _state = HandleState.Loading;
107→      }
108→    }
