111→  public void Initialize(AutomergeDocument document, bool isNewDocument = false)
112→  {
113→    ArgumentNullException.ThrowIfNull(document);
114→    EnsureNotDisposed();
115→
116→    lock(_stateGate)
117→    {
118→      if(_isInitialized)
119→      {
120→        throw new InvalidOperationException($"DocHandle '{DocumentId}' is already initialized.");
121→      }
122→
123→      _document = document;
124→      _isInitialized = true;
125→      _isNewDocument = isNewDocument;
126→      _state = HandleState.Ready;
127→      UpdateCachedHeads(document.GetHeads());
