166→  public void Unload()
167→  {
168→    lock(_stateGate)
169→    {
170→      _state = HandleState.Unloaded;
171→      _document = null;
172→      _currentHeads = Array.Empty<string>();
173→    }
174→  }
175→
176→  public void Reload()
177→  {
178→    lock(_stateGate)
179→    {
180→      if(_state == HandleState.Unloaded)
181→      {
182→        _state = HandleState.Loading;
183→      }
184→    }
185→  }
186→
187→  public void Delete()
188→  {
189→    lock(_stateGate)
190→    {
191→      _state = HandleState.Deleted;
192→    }
193→
194→    Deleted?.Invoke(this, new DocHandleDeletedEventArgs<T>(this));
