196→
197→  public void Dispose()
198→  {
199→    if(Interlocked.Exchange(ref _isDisposed, true))
200→    {
201→      return;
202→    }
203→
204→    AutomergeDocument? document;
205→    lock(_stateGate)
206→    {
207→      document = _document;
208→      _document = null;
209→      _state = HandleState.Unloaded;
210→      _currentHeads = Array.Empty<string>();
211→      _pendingLocalChanges.Clear();
212→    }
213→
214→    document?.Dispose();
215→    _documentLock.Dispose();
216→    _readySource.TrySetCanceled();
217→  }
