604→  public void NotifyRemoteChange(AutomergeDocument document)
605→  {
606→    EnsureNotDisposed();
607→    if(_state != HandleState.Ready)
608→    {
609→      return;
610→    }
611→
612→    _documentLock.Wait();
613→    try
614→    {
615→      UpdateCachedHeads(document.GetHeads());
616→    }
617→    finally
618→    {
619→      _documentLock.Release();
620→    }
621→
622→    OnChanged(null, isLocal: false, null);
623→  }
