625→  public async Task Merge(DocHandle<T> other)
626→  {
627→    if(other is null)
628→    {
629→      throw new ArgumentNullException(nameof(other));
630→    }
631→
632→    EnsureEditable();
633→
634→    bool hasChanges;
635→    await using(var mergeLock = await CompositeSemaphore.AcquireAsync(_documentLock, other._documentLock).ConfigureAwait(false))
636→    {
637→      var doc = DocInternal();
638→      var otherDoc = other.DocInternal();
639→
640→      var hashes = doc.Merge(otherDoc);
641→      hasChanges = hashes.Count > 0;
642→      if(hasChanges)
643→      {
644→        UpdateCachedHeads(doc.GetHeads());
645→      }
646→    }
647→
648→    if(hasChanges)
649→    {
650→      OnChanged(null, isLocal: true, null);
651→    }
652→  }
