 59→  public CollectionSynchronizer(
 60→    Func<string, AutomergeDocument?> getDocument,
 61→    Action<string, AutomergeDocument> updateDocument,
 62→    Func<PeerId, PeerMetadata?> getPeerMetadata,
 63→    Action<string> requestDocument,
