266→  /// <summary>
267→  /// Notifies the synchronizer that a local document change occurred.
268→  /// </summary>
269→  /// <param name="documentId">The document identifier.</param>
270→  public async Task NotifyDocumentChanged(string documentId)
271→  {
272→    ThrowIfDisposed();
273→
274→    DocSynchronizer? docSync;
275→
276→    await _lock.WaitAsync().ConfigureAwait(false);
277→    try
278→    {
279→      if(!_docSynchronizers.TryGetValue(documentId, out docSync))
280→      {
281→        return;
282→      }
283→    }
284→    finally
