  5→/// <summary>
  6→/// Manages synchronization for a single document across multiple peers.
  7→/// Maintains per-peer sync state and implements the Automerge sync protocol.
  8→/// </summary>
  9→internal sealed class DocSynchronizer : IDisposable
 10→{
 11→  readonly string _documentId;
 12→  readonly DocumentId _documentIdValue;
 13→  readonly Func<AutomergeDocument?> _getDocument;
 14→  readonly Action<AutomergeDocument> _updateDocument;
 15→  readonly Func<PeerId, PeerMetadata?> _getPeerMetadata;
 16→  readonly Func<SemaphoreSlim?> _getDocumentLock;
 17→
 18→  readonly Dictionary<PeerId, AutomergeSyncState> _syncStates = [];
 19→  readonly Dictionary<PeerId, PeerDocumentStatus> _peerStatuses = [];
 20→  readonly HashSet<PeerId> _activePeers = [];
 21→  readonly SemaphoreSlim _lock = new(1, 1);
 22→
 23→  int _messagesSent;
 24→  int _messagesReceived;
 25→  bool _disposed;
 26→
 27→  /// <summary>
 28→  /// Event fired when a message should be sent to a peer.
 29→  /// </summary>
 30→  public event EventHandler<SyncMessageEventArgs>? MessageToSend;
 31→
 32→  /// <summary>
 33→  /// Event fired when sync state changes (for persistence).
 34→  /// </summary>
 35→  public event EventHandler<SyncStateChangedEventArgs>? SyncStateChanged;
 36→
 37→  /// <summary>
 38→  /// Event fired when sync metrics are updated.
 39→  /// </summary>
 40→  public event EventHandler<SyncMetricsEventArgs>? MetricsUpdated;
 41→
 42→  /// <summary>
 43→  /// Creates a new DocSynchronizer for a specific document.
 44→  /// </summary>
 45→  /// <param name="documentId">The document ID being synchronized</param>
 46→  /// <param name="getDocument">Callback to retrieve the current document</param>
 47→  /// <param name="updateDocument">Callback to update the document after receiving changes</param>
 48→  /// <param name="getPeerMetadata">Callback to retrieve peer metadata</param>
 49→  /// <param name="getDocumentLock">Callback to retrieve the document lock for serializing FFI access</param>
 50→  public DocSynchronizer(
 51→    string documentId,
 52→    Func<AutomergeDocument?> getDocument,
 53→    Action<AutomergeDocument> updateDocument,
 54→    Func<PeerId, PeerMetadata?> getPeerMetadata,
 55→    Func<SemaphoreSlim?> getDocumentLock)
 56→  {
 57→    _documentId = documentId ?? throw new ArgumentNullException(nameof(documentId));
 58→    _documentIdValue = DocumentId.Parse(documentId);
 59→    _getDocument = getDocument ?? throw new ArgumentNullException(nameof(getDocument));
 60→    _updateDocument = updateDocument ?? throw new ArgumentNullException(nameof(updateDocument));
 61→    _getPeerMetadata = getPeerMetadata ?? throw new ArgumentNullException(nameof(getPeerMetadata));
 62→    _getDocumentLock = getDocumentLock ?? throw new ArgumentNullException(nameof(getDocumentLock));
 63→  }
