 65→  /// <summary>
 66→  /// Begins synchronization with a peer. Sends initial sync message.
 67→  /// </summary>
 68→  public async Task BeginSync(PeerId peerId)
 69→  {
 70→    ThrowIfDisposed();
 71→
 72→    // Collect events to fire after releasing lock
 73→    var deferredEvents = new List<Action>();
 74→
 75→    await _lock.WaitAsync().ConfigureAwait(false);
 76→    try
 77→    {
 78→      if(_activePeers.Contains(peerId))
 79→      {
 80→        return;
 81→      }
 82→
 83→      _activePeers.Add(peerId);
 84→
 85→      // Initialize status as unknown
 86→      if(!_peerStatuses.ContainsKey(peerId))
 87→      {
 88→        _peerStatuses[peerId] = PeerDocumentStatus.Unknown;
 89→      }
 90→
 91→      // Send initial sync message
 92→      SendSyncMessage(peerId, deferredEvents);
 93→    }
 94→    finally
 95→    {
 96→      _lock.Release();
 97→    }
 98→
 99→    // Fire all deferred events after releasing the lock
100→    foreach(var eventAction in deferredEvents)
101→    {
102→      eventAction();
103→    }
104→  }
105→
106→  /// <summary>
107→  /// Ends synchronization with a peer. Cleans up state.
108→  /// </summary>
109→  public async Task EndSync(PeerId peerId)
110→  {
111→    ThrowIfDisposed();
112→
113→    await _lock.WaitAsync().ConfigureAwait(false);
114→    try
115→    {
116→      _activePeers.Remove(peerId);
117→
118→      // Dispose sync state before removing
119→      if(_syncStates.TryGetValue(peerId, out var state))
120→      {
121→        state.Dispose();
122→      }
123→
124→      _syncStates.Remove(peerId);
125→      _peerStatuses.Remove(peerId);
126→    }
127→    finally
128→    {
129→      _lock.Release();
130→    }
131→  }
