133→  /// <summary>
134→  /// Checks if we're actively syncing with a peer.
135→  /// </summary>
136→  public async Task<bool> HasPeer(PeerId peerId)
137→  {
138→    ThrowIfDisposed();
139→
140→    await _lock.WaitAsync().ConfigureAwait(false);
141→    try
142→    {
143→      return _activePeers.Contains(peerId);
144→    }
145→    finally
146→    {
147→      _lock.Release();
148→    }
149→  }
