151→  /// <summary>
152→  /// Gets the current status of a peer for this document.
153→  /// </summary>
154→  public async Task<PeerDocumentStatus> GetPeerStatus(PeerId peerId)
155→  {
156→    ThrowIfDisposed();
157→
158→    await _lock.WaitAsync().ConfigureAwait(false);
159→    try
160→    {
161→      return _peerStatuses.TryGetValue(peerId, out var status)
162→        ? status
163→        : PeerDocumentStatus.Unknown;
164→    }
165→    finally
166→    {
167→      _lock.Release();
168→    }
169→  }
