171→  /// <summary>
172→  /// Receives and routes a message to appropriate handler.
173→  /// </summary>
174→  public async Task ReceiveMessage(IRepoMessage message, PeerId senderId)
175→  {
176→    ThrowIfDisposed();
177→
178→    _messagesReceived++;
179→
180→    // Collect events to fire after releasing lock
181→    var deferredEvents = new List<Action>();
182→
183→    await _lock.WaitAsync().ConfigureAwait(false);
184→    try
185→    {
186→      switch(message)
187→      {
188→        case SyncMessage sync:
189→          ReceiveSyncMessage(sync, senderId, deferredEvents);
190→          break;
191→
192→        case RequestMessage request:
193→          ReceiveRequestMessage(request, senderId, deferredEvents);
194→          break;
195→
196→        case DocumentUnavailableMessage unavail:
197→          ReceiveDocumentUnavailable(unavail, senderId);
198→          break;
199→        case DocumentSnapshotMessage snapshot:
200→          ReceiveDocumentSnapshot(snapshot, senderId);
201→          break;
202→
203→        default:
204→          // Unknown message type, ignore
205→          break;
206→      }
207→    }
208→    finally
209→    {
210→      _lock.Release();
211→    }
212→
213→    // Fire all deferred events after releasing the lock
214→    foreach(var eventAction in deferredEvents)
215→    {
216→      eventAction();
217→    }
218→  }
