220→  /// <summary>
221→  /// Processes incoming sync message using Automerge sync protocol.
222→  /// </summary>
223→  private void ReceiveSyncMessage(SyncMessage message, PeerId senderId, List<Action> deferredEvents,
224→    bool preserveWantsStatus = false)
225→  {
226→    // Validate message data
227→    if(message.Data is null)
228→    {
229→      return;
230→    }
231→
232→    // Get document (or create empty one if we don't have it yet)
233→    var doc = _getDocument();
234→    var isNewDocument = doc is null;
235→    if(doc is null)
236→    {
237→      // We don't have the document yet, but the peer is sending us data
238→      // Create an empty document to receive the sync data
239→      doc = AutomergeDocument.Create();
240→    }
241→
242→    // Get sync state for this peer
243→    var syncState = GetOrCreateSyncState(senderId);
244→
245→    var shouldRespond = true;
246→
247→    // Apply sync message using Automerge protocol
248→    // Note: Empty messages are valid in the sync protocol (they indicate "I have nothing new")
249→    // Note: The current API mutates both doc and syncState in place
250→    if(message.Data.Length > 0)
251→    {
252→      var docLock = _getDocumentLock();
253→      docLock?.Wait();
254→      try
255→      {
256→        doc.ReceiveSyncMessage(syncState, message.Data);
257→      }
258→      finally
259→      {
260→        docLock?.Release();
261→      }
262→
263→      // Notify owner that document was updated
264→      _updateDocument(doc);
265→    }
266→    else if(isNewDocument)
267→    {
268→      // No payload but we created a local document instance; ensure repo registers it.
269→      _updateDocument(doc);
270→      // Nothing additional to send back unless we still owe data (e.g., due to request).
271→      if(!preserveWantsStatus)
272→      {
273→        shouldRespond = false;
274→      }
275→    }
276→
277→    // Mark peer as having the document (unless we need to preserve Wants status from RequestMessage)
278→    if(!preserveWantsStatus || _peerStatuses[senderId] != PeerDocumentStatus.Wants)
279→    {
280→      _peerStatuses[senderId] = PeerDocumentStatus.Has;
281→    }
282→
283→    // Defer sync state changed event (for persistence)
284→    var peerMetadata = _getPeerMetadata(senderId);
285→    if(peerMetadata?.StorageId is not null && !peerMetadata.IsEphemeral)
286→    {
287→      var syncStateChangedArgs = new SyncStateChangedEventArgs
288→      {
289→        DocumentId = _documentIdValue, PeerId = senderId, SyncState = syncState, StorageId = peerMetadata.StorageId
290→      };
291→      deferredEvents.Add(() => SyncStateChanged?.Invoke(this, syncStateChangedArgs));
292→    }
293→
294→    // Send response sync message immediately (immediate feedback)
295→    // Note: SendSyncMessage will add its own metrics event to deferredEvents
296→    if(shouldRespond)
297→    {
298→      SendSyncMessage(senderId, deferredEvents);
299→    }
300→  }
