302→  /// <summary>
303→  /// Processes incoming request message (peer wants the document).
304→  /// </summary>
305→  private void ReceiveRequestMessage(RequestMessage message, PeerId senderId, List<Action> deferredEvents)
306→  {
307→    // Mark peer as wanting the document
308→    _peerStatuses[senderId] = PeerDocumentStatus.Wants;
309→
310→    // Get document
311→    var doc = _getDocument();
312→    if(doc is null)
313→    {
314→      // We don't have it either, defer sending unavailable message
315→      var unavailMessage = new DocumentUnavailableMessage { DocumentId = _documentIdValue };
316→
317→      var messageArgs = new SyncMessageEventArgs
318→      {
319→        DocumentId = _documentIdValue, TargetPeerId = senderId, Message = unavailMessage
320→      };
321→      deferredEvents.Add(() => MessageToSend?.Invoke(this, messageArgs));
322→      return;
323→    }
324→
325→    // Process as sync message (request is just a sync with empty state)
326→    // Pass preserveWantsStatus=true to keep the Wants status we just set
327→    var syncMsg = new SyncMessage { DocumentId = message.DocumentId, Data = message.Data, SenderId = senderId };
328→
329→    ReceiveSyncMessage(syncMsg, senderId, deferredEvents, preserveWantsStatus: true);
330→  }
