182→  public void Dispose()
183→  {
184→    if(_disposed)
185→    {
186→      return;
187→    }
188→
189→    _disposed = true;
190→
191→    // CRITICAL: Ensure all pending operations are committed before disposing the native document.
192→    // The Rust FFI library (automerge-0.7.0) panics during cleanup if there are uncommitted changes
193→    // because remove_actor() fails with "cant rewrite - actor is present" error.
194→    // This can occur if a document has pending operations that haven't been committed.
195→    // By calling Rollback(), we discard any uncommitted changes and ensure clean disposal.
196→    try
197→    {
198→      // Rollback any uncommitted transactions to ensure a clean state
199→      // This prevents the Rust layer from panicking during cleanup
200→      if (PendingOperations > 0)
201→      {
202→        Rollback();
203→      }
204→    }
205→    catch
206→    {
207→      // Ignore errors during rollback - we still need to dispose the document
208→    }
209→
210→    _doc.Dispose();
211→  }
