137→  /// <summary>
138→  /// Adds a network adapter to the subsystem.
139→  /// </summary>
140→  /// <param name="adapter">The adapter to add.</param>
141→  /// <exception cref="ArgumentNullException">Thrown if adapter is null.</exception>
142→  /// <exception cref="ObjectDisposedException">Thrown if the subsystem has been disposed.</exception>
143→  public void AddAdapter(INetworkAdapter adapter)
144→  {
145→    if(adapter is null) throw new ArgumentNullException(nameof(adapter));
146→    ThrowIfDisposed();
147→
148→    _lock.Wait();
149→    try
150→    {
151→      if(_adapters.Contains(adapter)) return;
152→
153→      _adapters.Add(adapter);
154→
155→      // Wire up events
156→      adapter.PeerCandidate += OnAdapterPeerCandidate;
157→      adapter.PeerDisconnected += OnAdapterPeerDisconnected;
158→      adapter.MessageReceived += OnAdapterMessageReceived;
159→    }
160→    finally
161→    {
162→      _lock.Release();
163→    }
164→  }
165→
166→  /// <summary>
167→  /// Removes a network adapter from the subsystem.
168→  /// </summary>
169→  /// <param name="adapter">The adapter to remove.</param>
170→  /// <exception cref="ArgumentNullException">Thrown if adapter is null.</exception>
171→  /// <exception cref="ObjectDisposedException">Thrown if the subsystem has been disposed.</exception>
172→  public void RemoveAdapter(INetworkAdapter adapter)
173→  {
174→    if(adapter is null) throw new ArgumentNullException(nameof(adapter));
175→    ThrowIfDisposed();
176→
177→    _lock.Wait();
178→    try
179→    {
180→      if(!_adapters.Remove(adapter)) return;
181→
182→      // Unwire events
183→      adapter.PeerCandidate -= OnAdapterPeerCandidate;
184→      adapter.PeerDisconnected -= OnAdapterPeerDisconnected;
185→      adapter.MessageReceived -= OnAdapterMessageReceived;
186→
187→      // Remove peers associated with this adapter
188→      var peersToRemove = _peerToAdapter
189→        .Where(kvp => kvp.Value == adapter)
190→        .Select(kvp => kvp.Key)
191→        .ToList();
192→
193→      foreach(var peer in peersToRemove)
194→      {
195→        _peerToAdapter.Remove(peer);
196→        _peerMetadata.Remove(peer);
197→      }
198→    }
199→    finally
200→    {
201→      _lock.Release();
202→    }
203→  }
204→
205→  /// <summary>
206→  /// Sends a message through the appropriate adapter(s).
207→  /// For messages with a target peer, sends via that peer's adapter.
208→  /// For broadcast messages, sends via all ready adapters.
209→  /// </summary>
210→  /// <param name="message">The message to send.</param>
211→  /// <exception cref="ArgumentNullException">Thrown if message is null.</exception>
212→  /// <exception cref="ObjectDisposedException">Thrown if the subsystem has been disposed.</exception>
213→  public void Send(IRepoMessage message)
214→  {
215→    if(message is null)
216→      throw new ArgumentNullException(nameof(message));
217→
218→    ThrowIfDisposed();
219→
220→    _lock.Wait();
221→    try
222→    {
223→      // If message has a target peer, route through that peer's adapter only.
224→      if(message.TargetPeerId is { } targetPeerId &&
225→         _peerToAdapter.TryGetValue(targetPeerId, out var targetAdapter))
226→      {
227→        if(targetAdapter.IsReady)
228→        {
229→          targetAdapter.Send(message);
230→        }
231→      }
232→      else
233→      {
234→        // No target peer or peer not found — broadcast to all ready adapters.
235→        foreach(var adapter in _adapters)
236→        {
237→          if(adapter.IsReady)
238→          {
239→            adapter.Send(message);
240→          }
241→        }
242→      }
243→    }
244→    finally
245→    {
246→      _lock.Release();
247→    }
248→  }
249→
250→  /// <summary>
251→  /// Waits for at least one adapter to be ready.
252→  /// </summary>
253→  /// <returns>A task that completes when at least one adapter is ready.</returns>
254→  /// <exception cref="ObjectDisposedException">Thrown if the subsystem has been disposed.</exception>
255→  public async Task WhenReady()
256→  {
257→    ThrowIfDisposed();
258→
259→    // Poll adapters until one is ready
260→    while(true)
261→    {
262→      await _lock.WaitAsync();
263→      try
264→      {
265→        if(_adapters.Any(a => a.IsReady))
266→          return;
267→      }
268→      finally
269→      {
270→        _lock.Release();
271→      }
272→
273→      // Wait a bit before checking again
274→      await Task.Delay(100);
275→    }
276→  }
277→
278→  /// <summary>
279→  /// Returns metadata for a peer, if available.
280→  /// </summary>
281→  /// <param name="peerId">The peer ID to look up.</param>
282→  /// <returns>The peer metadata, or null if not found.</returns>
283→  /// <exception cref="ObjectDisposedException">Thrown if the subsystem has been disposed.</exception>
284→  public PeerMetadata? GetPeerMetadata(PeerId peerId)
285→  {
286→    ThrowIfDisposed();
287→
288→    _lock.Wait();
289→    try
290→    {
291→      return _peerMetadata.TryGetValue(peerId, out var metadata) ? metadata : null;
292→    }
293→    finally
294→    {
295→      _lock.Release();
296→    }
297→  }
298→
299→
300→  // PRIVATE METHODS
301→  // ---------------------------------------------------------------------------------------------------------
302→  void OnAdapterPeerCandidate(object? sender, PeerCandidateEventArgs e)
303→  {
304→    if(sender is not INetworkAdapter adapter) return;
305→
306→    _lock.Wait();
307→    try
308→    {
309→      // Track peer-to-adapter mapping
310→      _peerToAdapter[e.PeerId] = adapter;
311→
312→      // Store peer metadata
313→      if(e.Metadata is not null)
314→      {
315→        _peerMetadata[e.PeerId] = e.Metadata;
316→      }
317→    }
318→    finally
319→    {
320→      _lock.Release();
321→    }
322→
323→    // Forward event to subscribers
324→    PeerCandidate?.Invoke(this, e);
325→  }
326→
327→  void OnAdapterPeerDisconnected(object? sender, PeerDisconnectedEventArgs e)
328→  {
329→    _lock.Wait();
330→    try
331→    {
332→      _peerToAdapter.Remove(e.PeerId);
333→      _peerMetadata.Remove(e.PeerId);
334→    }
335→    finally
336→    {
337→      _lock.Release();
338→    }
339→
340→    // Forward event to subscribers
341→    PeerDisconnected?.Invoke(this, e);
342→  }
343→
344→  void OnAdapterMessageReceived(object? sender, MessageReceivedEventArgs e)
345→  {
346→    var message = e.Message;
347→
348→    // Deduplicate ephemeral messages
349→    if(message is EphemeralMessage ephemeral)
350→    {
351→      if(!ShouldProcessEphemeralMessage(ephemeral))
352→      {
353→        // Already seen this message, skip
354→        return;
355→      }
356→    }
357→
358→    // Forward message to subscribers
359→    MessageReceived?.Invoke(this, e);
360→  }
361→
362→  /// <summary>
363→  /// Checks if ephemeral message should be processed (deduplication).
364→  /// Returns true if message is new, false if already seen.
365→  /// </summary>
366→  bool ShouldProcessEphemeralMessage(EphemeralMessage message)
367→  {
368→    // Create the unique key: peerId:sessionId:count
369→    var key = $"{message.SenderId}:{message.SessionId}:{message.Count}";
370→
371→    _lock.Wait();
372→    try
373→    {
374→      if(!_seenEphemeralMessages.Add(key))
375→        return false; // Already seen
376→
377→      // Add to seen set
378→      // Cleanup old entries periodically (keep last 1000)
379→      if(_seenEphemeralMessages.Count > 1000)
380→      {
381→        // Remove oldest half
382→        var toRemove = _seenEphemeralMessages.Take(500).ToList();
383→        foreach(var item in toRemove)
384→        {
385→          _seenEphemeralMessages.Remove(item);
386→        }
387→      }
388→
389→      return true; // New message
390→    }
391→    finally
392→    {
393→      _lock.Release();
394→    }
395→  }
396→
397→  void ThrowIfDisposed()
398→  {
399→    if(_isDisposed)
400→    {
401→      throw new ObjectDisposedException(nameof(NetworkSubsystem));
402→    }
403→  }
404→}

  1→using Six.Automerge.Repository;
  2→using Six.Automerge.Repo.Network.SignalR.Client;
  3→
  4→namespace Six.Automerge.Repo.Network.SignalR;
  5→
  6→/// <summary>
  7→/// SignalR-based network adapter for Automerge document synchronization.
  8→/// </summary>
  9→/// <remarks>
 10→/// This adapter provides real-time collaborative editing over ASP.NET Core SignalR with:
 11→/// <list type="bullet">
 12→///   <item><description>Automatic reconnection and connection lifecycle management</description></item>
 13→///   <item><description>MessagePack serialization with LZ4 compression for bandwidth efficiency</description></item>
 14→///   <item><description>Document-based group subscriptions for targeted message delivery</description></item>
 15→///   <item><description>Thread-safe operations with concurrent access support</description></item>
 16→/// </list>
 17→///
 18→/// <para>
 19→/// <strong>Usage Example:</strong>
 20→/// <code>
 21→/// var adapter = new SignalRNetworkAdapter(connectionService, loggerFactory);
 22→/// adapter.MessageReceived += (sender, args) => {
 23→///   Console.WriteLine($"Received: {args.Message.MessageType}");
 24→/// };
 25→/// adapter.Connect(PeerId.Generate(), null);
 26→/// await adapter.WhenReady();
 27→/// adapter.Send(syncMessage);
 28→/// </code>
 29→/// </para>
 30→/// </remarks>
 31→[PublicAPI]
 32→public sealed class SignalRNetworkAdapter : INetworkAdapter, IDocumentsHubClient, IDisposable, IAsyncDisposable
 33→{
 34→  readonly ISignalRConnectionService _connectionService;
 35→  readonly ILogger<SignalRNetworkAdapter> _logger;
 36→  readonly string _adapterId;
 37→  readonly SemaphoreSlim _lock = new(1, 1);
 38→  readonly TaskCompletionSource _readyTcs = new();
 39→  readonly ConcurrentDictionary<string, byte> _subscribedDocuments = new();
 40→
 41→  HubConnection? _connection;
 42→  PeerId? _peerId;
 43→  bool _isReady;
 44→  bool _disposed;
 45→
 46→  /// <summary>
 47→  /// Initializes a new instance of the <see cref="SignalRNetworkAdapter"/> class.
 48→  /// </summary>
 49→  /// <param name="connectionService">The SignalR connection service.</param>
 50→  /// <param name="loggerFactory">The logger factory.</param>
 51→  public SignalRNetworkAdapter(
 52→    ISignalRConnectionService connectionService,
 53→    ILoggerFactory loggerFactory)
 54→  {
 55→    _connectionService = connectionService ?? throw new ArgumentNullException(nameof(connectionService));
 56→    ArgumentNullException.ThrowIfNull(loggerFactory);
 57→
 58→    _logger = loggerFactory.CreateLogger<SignalRNetworkAdapter>();
 59→    _adapterId = $"signalr-{Guid.NewGuid():N}";
 60→  }
 61→
 62→  /// <inheritdoc />
 63→  public string AdapterId => _adapterId;
 64→
 65→  /// <inheritdoc />
 66→  public bool IsReady => _isReady;
 67→
 68→  /// <inheritdoc />
 69→  public Task WhenReady() => _readyTcs.Task;
 70→
 71→  /// <inheritdoc />
 72→  public event EventHandler<PeerCandidateEventArgs>? PeerCandidate;
 73→
 74→  /// <inheritdoc />
 75→  public event EventHandler<PeerDisconnectedEventArgs>? PeerDisconnected;
 76→
 77→  /// <inheritdoc />
 78→  public event EventHandler<MessageReceivedEventArgs>? MessageReceived;
 79→
 80→  /// <inheritdoc />
 81→  public event EventHandler? Closed;
 82→
 83→  /// <inheritdoc />
 84→  public void Connect(PeerId peerId, PeerMetadata? metadata = null)
 85→  {
 86→    if (_disposed)
 87→      throw new ObjectDisposedException(nameof(SignalRNetworkAdapter));
 88→
 89→    _ = ConnectAsyncInternal(peerId, metadata);
 90→  }
 91→
 92→  async Task ConnectAsyncInternal(PeerId peerId, PeerMetadata? metadata)
 93→  {
 94→    await _lock.WaitAsync();
 95→    try
 96→    {
 97→      if (_isReady)
 98→      {
 99→        _logger.LogWarning("Adapter already connected. Ignoring duplicate Connect call.");
100→        return;
101→      }
102→
103→      _logger.LogInformation("Connecting SignalR adapter for peer: {PeerId}", peerId);
104→      _peerId = peerId;
105→
106→      // Get connection from service
107→      _connection = await _connectionService.GetConnection();
108→      _logger.LogDebug("SignalR connection established. ConnectionId={ConnectionId}", _connection.ConnectionId ?? "<pending>");
109→
110→      // Register client methods for hub callbacks
111→      _logger.LogDebug("Registering hub callbacks for connection {ConnectionId}", _connection.ConnectionId ?? "<pending>");
112→      _connection.On<MessageDto>(
113→        "OnReceiveMessage",
114→        msg =>
115→        {
116→          _logger.LogTrace("Hub invoked OnReceiveMessage. DocumentId={DocumentId}, MessageType={MessageType}, SenderId={SenderId}",
117→            msg.DocumentId,
118→            msg.MessageType,
119→            msg.SenderId);
120→          _ = ((IDocumentsHubClient)this).OnReceiveMessage(msg);
121→        });
122→      _connection.On<PeerHandshakeDto>(
123→        "OnPeerJoined",
124→        handshake =>
125→        {
126→          _logger.LogTrace("Hub invoked OnPeerJoined for PeerId={PeerId}", handshake.PeerId);
127→          _ = ((IDocumentsHubClient)this).OnPeerJoined(handshake);
128→        });
129→      _connection.On<string>(
130→        "OnPeerLeft",
131→        peerId =>
132→        {
133→          _logger.LogTrace("Hub invoked OnPeerLeft for PeerId={PeerId}", peerId);
134→          _ = ((IDocumentsHubClient)this).OnPeerLeft(peerId);
135→        });
136→
137→      // Hook connection lifecycle events
138→      _connection.Closed += OnConnectionClosedAsync;
139→
140→      // Send handshake and receive the server's identity
141→      var handshake = PeerHandshakeDto.Create(peerId, metadata);
142→      var serverHandshake = await _connection.InvokeAsync<PeerHandshakeDto>("Handshake", handshake);
143→
144→      _logger.LogInformation(
145→        "Handshake completed for peer: {PeerId}. Server peer: {ServerPeerId}",
146→        peerId, serverHandshake.PeerId);
147→
148→      // Mark ready
149→      _isReady = true;
150→      _readyTcs.TrySetResult();
151→
152→      // Raise PeerCandidate with the SERVER's PeerId (our direct peer),
153→      // not our own PeerId
154→      var serverPeerId = new PeerId(serverHandshake.PeerId);
155→      var serverMetadata = serverHandshake.Metadata?.ToPeerMetadata();
156→      RaisePeerCandidate(serverPeerId, serverMetadata);
157→    }
158→    catch (Exception ex)
159→    {
160→      _logger.LogError(ex, "Failed to connect SignalR adapter for peer: {PeerId}", peerId);
161→      _readyTcs.TrySetException(ex);
162→      throw;
163→    }
164→    finally
165→    {
166→      _lock.Release();
167→    }
168→  }
169→
170→  /// <inheritdoc />
171→  public void Send(IRepoMessage message)
172→  {
173→    if (_disposed)
174→      throw new ObjectDisposedException(nameof(SignalRNetworkAdapter));
175→
176→    ArgumentNullException.ThrowIfNull(message);
177→
178→    _ = SendAsyncInternal(message);
179→  }
180→
181→  async Task SendAsyncInternal(IRepoMessage message)
182→  {
183→    await _lock.WaitAsync();
184→    try
185→    {
186→      if (!_isReady || _connection is null)
187→      {
188→        _logger.LogWarning("Cannot send message: adapter not ready or connection is null");
189→        return;
190→      }
191→
192→      var documentId = message.DocumentId;
193→
194→      if (documentId is null)
195→      {
196→        _logger.LogWarning("Cannot send message: DocumentId is null or empty");
197→        return;
198→      }
199→
200→      if (_peerId is null)
201→      {
202→        _logger.LogWarning("Cannot send message type {MessageType}: adapter has no peer ID assigned", message.MessageType);
203→        return;
204→      }
205→
206→      // Auto-subscribe to document if not already subscribed
207→      var documentIdValue = documentId.Value;
208→      var documentIdString = documentIdValue.Value;
209→
210→      if (!_subscribedDocuments.ContainsKey(documentIdString))
211→      {
212→        _logger.LogDebug("Auto-subscribing to document: {DocumentId}", documentIdString);
213→        await SubscribeToDocumentInternalAsync(documentIdString);
214→      }
215→
216→      var messageWithSender = EnsureSender(message, _peerId.Value);
217→
218→      if (messageWithSender.SenderId is null && messageWithSender is DocumentSnapshotMessage snapshotWithoutSender)
219→      {
220→        messageWithSender = snapshotWithoutSender with { SenderId = _peerId.Value };
221→      }
222→
223→      _logger.LogInformation(
224→        "Sending {MessageType} message for document {DocumentId} via SignalR connection {ConnectionId} as sender {SenderId}",
225→        messageWithSender.MessageType,
226→        messageWithSender.DocumentId?.Value,
227→        _connection.ConnectionId ?? "<pending>",
228→        messageWithSender.SenderId?.ToString());
229→
230→      // Create MessageDto
231→      var messageData = GetMessageData(messageWithSender);
232→      var messageDto = MessageDto.FromRepoMessage(messageWithSender, messageData!);
233→
234→      // Send to hub
235→      await _connection.InvokeAsync("SendMessage", messageDto);
236→
237→      _logger.LogInformation("Hub accepted {MessageType} message for document {DocumentId} on connection {ConnectionId}",
238→        messageWithSender.MessageType,
239→        messageWithSender.DocumentId?.Value,
240→        _connection.ConnectionId ?? "<pending>");
241→    }
242→    catch (Exception ex)
243→    {
244→      _logger.LogError(ex, "Failed to send message type {MessageType} for document {DocumentId}",
245→        message.MessageType, message.DocumentId?.Value);
246→    }
247→    finally
248→    {
249→      _lock.Release();
250→    }
251→  }
252→
253→  /// <summary>
254→  /// Subscribes to a document to receive sync messages.
255→  /// </summary>
256→  /// <param name="documentId">The document ID to subscribe to.</param>
257→  public async Task SubscribeToDocumentAsync(string documentId)
258→  {
259→    if (_disposed)
260→      throw new ObjectDisposedException(nameof(SignalRNetworkAdapter));
261→
262→    ArgumentException.ThrowIfNullOrEmpty(documentId);
263→
264→    await _lock.WaitAsync();
265→    try
266→    {
267→      await SubscribeToDocumentInternalAsync(documentId);
268→    }
269→    finally
270→    {
271→      _lock.Release();
272→    }
273→  }
