275→  async Task SubscribeToDocumentInternalAsync(string documentId)
276→  {
277→    if (_subscribedDocuments.ContainsKey(documentId))
278→    {
279→      _logger.LogDebug("Already subscribed to document: {DocumentId}", documentId);
280→      return;
281→    }
