296→  /// Unsubscribes from a document.
297→  /// </summary>
298→  /// <param name="documentId">The document ID to unsubscribe from.</param>
299→  public async Task UnsubscribeFromDocumentAsync(string documentId)
300→  {
301→    if (_disposed)
302→      throw new ObjectDisposedException(nameof(SignalRNetworkAdapter));
303→
304→    ArgumentException.ThrowIfNullOrEmpty(documentId);
305→
306→    await _lock.WaitAsync();
307→    try
308→    {
309→      await UnsubscribeFromDocumentInternalAsync(documentId);
310→    }
311→    finally
312→    {
313→      _lock.Release();
314→    }
315→  }
316→
317→  async Task UnsubscribeFromDocumentInternalAsync(string documentId)
318→  {
319→    if (!_subscribedDocuments.ContainsKey(documentId))
320→    {
321→      _logger.LogDebug("Not subscribed to document: {DocumentId}", documentId);
322→      return;
323→    }
324→
325→    if (_connection is null)
326→    {
327→      _logger.LogWarning("Cannot unsubscribe: connection is null");
328→      return;
329→    }
330→
331→    await _connection.InvokeAsync("UnsubscribeFromDocument", documentId);
332→    _subscribedDocuments.TryRemove(documentId, out _);
