  3→using Microsoft.AspNetCore.SignalR;
  4→using Microsoft.Extensions.Logging;
  5→using Six.Automerge.Repository;
  6→using Six.Automerge.Repository.Network;
  7→using Six.Automerge.Repository.Network.SignalR;
  8→using Server.Api.Services;
  9→
 10→namespace Server.Api.Hubs;
 11→
 12→/// <summary>
 13→/// Abstract base class for per-app collaborative hubs. Each concrete hub sets its
 14→/// <see cref="AppType"/> and inherits all document sync operations.
 15→/// </summary>
 16→/// <remarks>
 17→/// Unlike the library's <c>DocumentsHub</c> which directly relays messages between clients,
 18→/// this hub routes all messages through a server-side <see cref="CollaborativeHubAdapter"/>
 19→/// and <see cref="Repo"/>, enabling the server to participate in document synchronization.
 20→/// </remarks>
 21→[PublicAPI]
 22→public abstract class CollaborativeHub : Hub<ICollaborativeHubClient>
 23→{
 24→  readonly ServerRepoManager _repoManager;
 25→  readonly CollaborativeHubAdapter _adapter;
 26→  readonly ILogger _logger;
 27→
 28→  /// <summary>
 29→  /// Initializes a new instance of the <see cref="CollaborativeHub"/> class.
 30→  /// </summary>
 31→  protected CollaborativeHub(
 32→    ServerRepoManager repoManager,
 33→    CollaborativeHubAdapter adapter,
 34→    ILoggerFactory loggerFactory)
 35→  {
 36→    ArgumentNullException.ThrowIfNull(repoManager);
 37→    ArgumentNullException.ThrowIfNull(adapter);
 38→    ArgumentNullException.ThrowIfNull(loggerFactory);
 39→
 40→    _repoManager = repoManager;
 41→    _adapter = adapter;
 42→    _logger = loggerFactory.CreateLogger(GetType());
 43→  }
 44→
 45→  /// <summary>
 46→  /// Gets the app type identifier for this hub (e.g., "text-editor", "drawing").
 47→  /// </summary>
 48→  public abstract string AppType { get; }
 49→
 50→  /// <summary>
 51→  /// Establishes peer identity. Notifies the server adapter and broadcasts to other clients.
 52→  /// Ensures the server-side Repo is initialized so incoming sync messages are processed.
 53→  /// </summary>
 54→  public async Task<PeerHandshakeDto> Handshake(PeerHandshakeDto handshake)
 55→  {
 56→    try
 57→    {
 58→      _logger.LogInformation(
 59→        "Peer handshake on {AppType} hub: PeerId={PeerId}, ConnectionId={ConnectionId}",
 60→        AppType, handshake.PeerId, Context.ConnectionId);
 61→
 62→      // Ensure the server-side Repo exists and is listening to adapter events.
 63→      // GetRepo is idempotent — it creates on first call and returns cached thereafter.
 64→      var repo = _repoManager.GetRepo(AppType);
 65→      _logger.LogDebug("Server repo ready for {AppType}. PeerId={ServerPeerId}", AppType, repo.PeerId);
 66→
 67→      Context.Items["PeerId"] = handshake.PeerId;
 68→
 69→      var peerId = new PeerId(handshake.PeerId);
 70→      var metadata = handshake.Metadata?.ToPeerMetadata();
 71→      _adapter.OnClientConnected(Context.ConnectionId, peerId, metadata);
 72→
 73→      await Clients.Others.OnPeerJoined(handshake);
 74→
 75→      // Return the server's PeerId so the client knows who its direct peer is
 76→      return PeerHandshakeDto.Create(repo.PeerId, null);
 77→    }
 78→    catch(Exception ex)
 79→    {
 80→      _logger.LogError(ex, "Error during handshake on {AppType} hub. ConnectionId={ConnectionId}",
 81→        AppType, Context.ConnectionId);
 82→      throw;
 83→    }
 84→  }
 85→
 86→  /// <summary>
 87→  /// Routes a sync message through the server adapter and Repo.
 88→  /// Does NOT directly relay to other clients — the Repo generates and sends responses.
 89→  /// </summary>
 90→  public async Task SendMessage(MessageDto message)
 91→  {
 92→    try
 93→    {
 94→      if(string.IsNullOrEmpty(message.DocumentId))
 95→      {
 96→        _logger.LogWarning(
 97→          "Received message with empty DocumentId on {AppType} hub. ConnectionId={ConnectionId}",
 98→          AppType, Context.ConnectionId);
 99→        return;
100→      }
101→
102→      _logger.LogDebug(
103→        "Routing message on {AppType} hub: DocumentId={DocumentId}, MessageType={MessageType}, SenderId={SenderId}",
104→        AppType, message.DocumentId, message.MessageType, message.SenderId);
105→
106→      // Auto-subscribe sender to document group
107→      await Groups.AddToGroupAsync(Context.ConnectionId, message.DocumentId);
108→
109→      // Route through the server adapter → Repo, NOT direct relay
110→      var repoMessage = DeserializeMessage(message);
111→      if(repoMessage is not null)
112→      {
113→        var senderId = new PeerId(message.SenderId);
114→        _adapter.OnClientMessage(senderId, repoMessage);
115→      }
116→    }
117→    catch(Exception ex)
118→    {
119→      _logger.LogError(ex,
120→        "Error routing message on {AppType} hub. DocumentId={DocumentId}, ConnectionId={ConnectionId}",
121→        AppType, message.DocumentId, Context.ConnectionId);
122→    }
123→  }
124→
125→  /// <summary>
126→  /// Subscribes the calling client to a document group.
127→  /// </summary>
128→  public async Task SubscribeToDocument(string documentId)
129→  {
130→    try
131→    {
132→      if(string.IsNullOrEmpty(documentId))
133→      {
134→        _logger.LogWarning("Subscribe with empty documentId on {AppType} hub. ConnectionId={ConnectionId}",
135→          AppType, Context.ConnectionId);
136→        return;
137→      }
138→
139→      await Groups.AddToGroupAsync(Context.ConnectionId, documentId);
140→
141→      _logger.LogInformation(
142→        "Client subscribed to document on {AppType} hub: DocumentId={DocumentId}, ConnectionId={ConnectionId}",
143→        AppType, documentId, Context.ConnectionId);
144→    }
145→    catch(Exception ex)
146→    {
147→      _logger.LogError(ex, "Error subscribing on {AppType} hub. DocumentId={DocumentId}, ConnectionId={ConnectionId}",
148→        AppType, documentId, Context.ConnectionId);
149→    }
150→  }
151→
152→  /// <summary>
153→  /// Unsubscribes the calling client from a document group.
154→  /// </summary>
155→  public async Task UnsubscribeFromDocument(string documentId)
156→  {
157→    try
158→    {
159→      if(string.IsNullOrEmpty(documentId))
160→      {
161→        _logger.LogWarning("Unsubscribe with empty documentId on {AppType} hub. ConnectionId={ConnectionId}",
162→          AppType, Context.ConnectionId);
163→        return;
164→      }
165→
166→      await Groups.RemoveFromGroupAsync(Context.ConnectionId, documentId);
167→
168→      _logger.LogInformation(
169→        "Client unsubscribed from document on {AppType} hub: DocumentId={DocumentId}, ConnectionId={ConnectionId}",
170→        AppType, documentId, Context.ConnectionId);
171→    }
172→    catch(Exception ex)
173→    {
174→      _logger.LogError(ex, "Error unsubscribing on {AppType} hub. DocumentId={DocumentId}, ConnectionId={ConnectionId}",
175→        AppType, documentId, Context.ConnectionId);
176→    }
177→  }
178→
179→  /// <summary>
180→  /// Returns the list of document IDs stored for this hub's app type.
181→  /// </summary>
182→  public Task<List<string>> ListDocuments()
183→  {
184→    try
185→    {
186→      var docs = _repoManager.ListDocuments(AppType);
187→
188→      _logger.LogDebug("Listed {Count} documents for {AppType} hub", docs.Count, AppType);
189→
190→      return Task.FromResult(docs.ToList());
191→    }
192→    catch(Exception ex)
193→    {
194→      _logger.LogError(ex, "Error listing documents on {AppType} hub", AppType);
195→      return Task.FromResult(new List<string>());
196→    }
197→  }
198→
199→  /// <inheritdoc />
200→  public override Task OnConnectedAsync()
201→  {
202→    _logger.LogInformation("Client connected to {AppType} hub: ConnectionId={ConnectionId}",
203→      AppType, Context.ConnectionId);
204→    return base.OnConnectedAsync();
205→  }
206→
207→  /// <inheritdoc />
208→  public override async Task OnDisconnectedAsync(Exception? exception)
209→  {
210→    var peerId = Context.Items.TryGetValue("PeerId", out var id) ? id?.ToString() : null;
211→
212→    if(exception is not null)
213→    {
214→      _logger.LogWarning(exception,
215→        "Client disconnected with error from {AppType} hub: ConnectionId={ConnectionId}, PeerId={PeerId}",
216→        AppType, Context.ConnectionId, peerId ?? "unknown");
217→    }
218→    else
219→    {
220→      _logger.LogInformation(
221→        "Client disconnected from {AppType} hub: ConnectionId={ConnectionId}, PeerId={PeerId}",
222→        AppType, Context.ConnectionId, peerId ?? "unknown");
223→    }
224→
225→    if(!string.IsNullOrEmpty(peerId))
226→    {
227→      _adapter.OnClientDisconnected(Context.ConnectionId, new PeerId(peerId));
228→      await Clients.Others.OnPeerLeft(peerId);
229→    }
230→
231→    await base.OnDisconnectedAsync(exception);
232→  }
233→
234→  static IRepoMessage? DeserializeMessage(MessageDto messageDto)
235→  {
236→    var senderId = new PeerId(messageDto.SenderId);
237→
238→    return messageDto.MessageType switch
239→    {
240→      "sync" => new SyncMessage
241→      {
242→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
243→        Data = messageDto.Data,
244→        SenderId = senderId
245→      },
246→      "request" => new RequestMessage
247→      {
248→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
249→        Data = messageDto.Data,
250→        SenderId = senderId
251→      },
252→      "doc-unavailable" => new DocumentUnavailableMessage
253→      {
254→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
255→        SenderId = senderId
256→      },
257→      "doc-snapshot" => new DocumentSnapshotMessage
258→      {
259→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
260→        Data = messageDto.Data ?? [],
261→        SenderId = senderId
262→      },
263→      _ => null
264→    };
265→  }
266→}
