  3→using System.Collections.Concurrent;
  4→using Microsoft.Extensions.Logging;
  5→using Six.Automerge.Repository;
  6→using Six.Automerge.Repository.Network;
  7→using Six.Automerge.Repository.Network.SignalR;
  8→
  9→namespace Server.Api.Hubs;
 10→
 11→/// <summary>
 12→/// Per-app-type <see cref="INetworkAdapter"/> that bridges a <see cref="CollaborativeHub"/>
 13→/// to a server-side <see cref="Repo"/>. Each app type gets its own adapter instance.
 14→/// </summary>
 15→/// <remarks>
 16→/// Unlike <see cref="Network.SignalRServerNetworkAdapter"/> which is coupled to <c>DocumentsHub</c>,
 17→/// this adapter uses a delegate to send messages to the correct hub's clients. This enables
 18→/// per-app hub routing without tight coupling to concrete hub types.
 19→/// </remarks>
 20→[PublicAPI]
 21→public sealed class CollaborativeHubAdapter : INetworkAdapter, IDisposable
 22→{
 23→  readonly string _appType;
 24→  readonly Func<string, ICollaborativeHubClient> _getGroupClients;
 25→  readonly Func<string, ICollaborativeHubClient> _getClientByConnection;
 26→  readonly ILogger<CollaborativeHubAdapter> _logger;
 27→  readonly string _adapterId;
 28→  readonly ConcurrentDictionary<string, string> _peerToConnection = new(); // PeerId → ConnectionId
 29→  readonly ConcurrentDictionary<string, string> _connectionToPeer = new(); // ConnectionId → PeerId
 30→
 31→  bool _isReady = true;
 32→  bool _disposed;
 33→
 34→  /// <summary>
 35→  /// Initializes a new instance of the <see cref="CollaborativeHubAdapter"/> class.
 36→  /// </summary>
 37→  /// <param name="appType">The app type this adapter serves (e.g., "text-editor").</param>
 38→  /// <param name="getGroupClients">
 39→  /// Delegate that resolves a hub client proxy for a SignalR group name.
 40→  /// Typically backed by <c>IHubContext&lt;THub&gt;.Clients.Group(groupName)</c>.
 41→  /// </param>
 42→  /// <param name="getClientByConnection">
 43→  /// Delegate that resolves a hub client proxy for a specific SignalR connection ID.
 44→  /// Typically backed by <c>IHubContext&lt;THub&gt;.Clients.Client(connectionId)</c>.
 45→  /// Used for targeted per-peer message delivery instead of group broadcast.
 46→  /// </param>
 47→  /// <param name="loggerFactory">Logger factory.</param>
 48→  public CollaborativeHubAdapter(
 49→    string appType,
 50→    Func<string, ICollaborativeHubClient> getGroupClients,
 51→    Func<string, ICollaborativeHubClient> getClientByConnection,
 52→    ILoggerFactory loggerFactory)
 53→  {
 54→    ArgumentException.ThrowIfNullOrWhiteSpace(appType);
 55→    ArgumentNullException.ThrowIfNull(getGroupClients);
 56→    ArgumentNullException.ThrowIfNull(getClientByConnection);
 57→    ArgumentNullException.ThrowIfNull(loggerFactory);
 58→
 59→    _appType = appType;
 60→    _getGroupClients = getGroupClients;
 61→    _getClientByConnection = getClientByConnection;
 62→    _logger = loggerFactory.CreateLogger<CollaborativeHubAdapter>();
 63→    _adapterId = $"collaborative-hub-{appType}-{Guid.NewGuid():N}";
 64→  }
 65→
 66→  /// <summary>
 67→  /// Gets the app type this adapter serves.
 68→  /// </summary>
 69→  public string AppType => _appType;
 70→
 71→  /// <inheritdoc />
 72→  public string AdapterId => _adapterId;
 73→
 74→  /// <inheritdoc />
 75→  public bool IsReady => _isReady;
 76→
 77→  /// <inheritdoc />
 78→  public Task WhenReady() => Task.CompletedTask;
 79→
 80→  /// <inheritdoc />
 81→  public event EventHandler<PeerCandidateEventArgs>? PeerCandidate;
 82→
 83→  /// <inheritdoc />
 84→  public event EventHandler<PeerDisconnectedEventArgs>? PeerDisconnected;
 85→
 86→  /// <inheritdoc />
 87→  public event EventHandler<MessageReceivedEventArgs>? MessageReceived;
 88→
 89→  /// <inheritdoc />
 90→  public event EventHandler? Closed;
 91→
 92→  /// <inheritdoc />
 93→  public void Connect(PeerId peerId, PeerMetadata? metadata = null)
 94→  {
 95→    // No-op: server adapter is always ready.
 96→    _logger.LogDebug("Connect called on collaborative hub adapter (no-op). AppType={AppType}, PeerId={PeerId}",
 97→      _appType, peerId);
 98→  }
 99→
100→  /// <inheritdoc />
101→  public void Send(IRepoMessage message)
102→  {
103→    if(_disposed)
104→      return;
105→
106→    ArgumentNullException.ThrowIfNull(message);
107→
108→    _ = SendAsyncInternal(message);
109→  }
110→
111→  /// <inheritdoc />
112→  public Task Disconnect()
113→  {
114→    _isReady = false;
115→    _peerToConnection.Clear();
116→    _connectionToPeer.Clear();
117→
118→    _logger.LogInformation("Collaborative hub adapter disconnected. AppType={AppType}", _appType);
119→
120→    Closed?.Invoke(this, EventArgs.Empty);
121→
122→    return Task.CompletedTask;
123→  }
124→
125→  /// <summary>
126→  /// Called by the hub when a client completes handshake.
127→  /// Tracks the peer-to-connection mapping and raises <see cref="PeerCandidate"/>.
128→  /// </summary>
129→  public void OnClientConnected(string connectionId, PeerId peerId, PeerMetadata? metadata)
130→  {
131→    _peerToConnection[peerId] = connectionId;
132→    _connectionToPeer[connectionId] = peerId;
133→
134→    _logger.LogInformation(
135→      "Client connected to {AppType} hub adapter. PeerId={PeerId}, ConnectionId={ConnectionId}",
136→      _appType, peerId, connectionId);
137→
138→    PeerCandidate?.Invoke(this, new PeerCandidateEventArgs
139→    {
140→      PeerId = peerId,
141→      Metadata = metadata
142→    });
143→  }
144→
145→  /// <summary>
146→  /// Called by the hub when a client disconnects.
147→  /// Removes the mapping and raises <see cref="PeerDisconnected"/>.
148→  /// </summary>
149→  public void OnClientDisconnected(string connectionId, PeerId peerId)
150→  {
151→    _peerToConnection.TryRemove(peerId, out _);
152→    _connectionToPeer.TryRemove(connectionId, out _);
153→
154→    _logger.LogInformation(
155→      "Client disconnected from {AppType} hub adapter. PeerId={PeerId}, ConnectionId={ConnectionId}",
156→      _appType, peerId, connectionId);
157→
158→    PeerDisconnected?.Invoke(this, new PeerDisconnectedEventArgs
159→    {
160→      PeerId = peerId
161→    });
162→  }
163→
164→  /// <summary>
165→  /// Called by the hub when a client sends a message.
166→  /// Raises <see cref="MessageReceived"/> for the server-side Repo.
167→  /// </summary>
168→  public void OnClientMessage(PeerId senderId, IRepoMessage message)
169→  {
170→    _logger.LogDebug(
171→      "Received message from client on {AppType} hub. SenderId={SenderId}, MessageType={MessageType}, DocumentId={DocumentId}",
172→      _appType, senderId, message.MessageType, message.DocumentId?.Value);
173→
174→    MessageReceived?.Invoke(this, new MessageReceivedEventArgs
175→    {
176→      Message = message
177→    });
178→  }
179→
180→  /// <summary>
181→  /// Gets the number of currently connected peers.
182→  /// </summary>
183→  public int GetConnectedPeerCount() => _peerToConnection.Count;
184→
185→  async Task SendAsyncInternal(IRepoMessage message)
186→  {
187→    try
188→    {
189→      var documentId = message.DocumentId;
190→
191→      if(documentId is null)
192→      {
193→        _logger.LogWarning("Cannot send message: DocumentId is null. AppType={AppType}, MessageType={MessageType}",
194→          _appType, message.MessageType);
195→        return;
196→      }
197→
198→      if(message.SenderId is null)
199→      {
200→        _logger.LogWarning("Cannot send message: SenderId is null. AppType={AppType}, MessageType={MessageType}",
201→          _appType, message.MessageType);
202→        return;
203→      }
204→
205→      var messageData = GetMessageData(message);
206→      var messageDto = MessageDto.FromRepoMessage(message, messageData ?? []);
207→
208→      // If the message targets a specific peer and we know their connection, send directly.
209→      if(message.TargetPeerId is { } targetPeerId &&
210→         _peerToConnection.TryGetValue(targetPeerId, out var connectionId))
211→      {
212→        _logger.LogDebug(
213→          "Sending {MessageType} to peer {TargetPeerId} (connection {ConnectionId}) on {AppType} hub. SenderId={SenderId}",
214→          message.MessageType, (string)targetPeerId, connectionId, _appType, message.SenderId);
215→
216→        await _getClientByConnection(connectionId).OnReceiveMessage(messageDto);
217→        return;
218→      }
219→
220→      // Fallback: broadcast to the document group.
221→      _logger.LogDebug("Sending {MessageType} to group {DocumentId} on {AppType} hub. SenderId={SenderId}",
222→        message.MessageType, documentId.Value.Value, _appType, message.SenderId);
223→
224→      await _getGroupClients(documentId.Value.Value).OnReceiveMessage(messageDto);
225→    }
226→    catch(Exception ex)
227→    {
228→      _logger.LogError(ex, "Failed to send message on {AppType} hub. MessageType={MessageType}, DocumentId={DocumentId}",
229→        _appType, message.MessageType, message.DocumentId?.Value);
230→    }
231→  }
232→
233→  static byte[]? GetMessageData(IRepoMessage message)
234→  {
235→    return message switch
236→    {
237→      SyncMessage sync => sync.Data,
238→      RequestMessage request => request.Data,
239→      EphemeralMessage ephemeral => ephemeral.Data,
240→      DocumentUnavailableMessage => [],
241→      DocumentSnapshotMessage snapshot => snapshot.Data,
242→      _ => null
243→    };
244→  }
245→
246→  /// <inheritdoc />
247→  public void Dispose()
248→  {
249→    if(_disposed)
250→      return;
251→
252→    _disposed = true;
253→    _isReady = false;
254→    _peerToConnection.Clear();
255→    _connectionToPeer.Clear();
256→  }
257→}
