  6→public static class InteropExtensions
  7→{
  8→  public static string AsManagedString(this Native.Utf8String value)
  9→  {
 10→    try
 11→    {
 12→      return value.String;
 13→    }
 14→    finally
 15→    {
 16→      value.Dispose();
 17→    }
 18→  }
 19→
 20→  public static byte[] AsManagedBytes(this Native.ByteArray value)
 21→  {
 22→    try
 23→    {
 24→      return CopyVecU8(value.data, disposeVec: false);
 25→    }
 26→    finally
 27→    {
 28→      value.Dispose();
 29→    }
 30→  }
 31→
 32→  public static byte[]? AsManagedBytes(this Native.OptionByteArray option)
 33→  {
 34→    try
 35→    {
 36→      if(option.IsSome)
 37→      {
 38→        using var some = option.AsSome();
 39→        return some.AsManagedBytes();
 40→      }
 41→
 42→      return null;
 43→    }
 44→    finally
 45→    {
 46→      option.Dispose();
 47→    }
 48→  }
 49→
 50→  public static byte[] AsManagedBytes(this Native.ChangeBytes value)
 51→  {
 52→    try
 53→    {
 54→      return CopyVecU8(value.bytes, disposeVec: false);
 55→    }
 56→    finally
 57→    {
 58→      value.Dispose();
 59→    }
 60→  }
 61→
 62→  public static byte[] AsManagedBytes(this Native.ChangeHashBytes value)
 63→  {
 64→    byte[] bytes = new byte[32];
 65→    BinaryPrimitives.WriteUInt64LittleEndian(bytes.AsSpan(0, 8), value.part1);
 66→    BinaryPrimitives.WriteUInt64LittleEndian(bytes.AsSpan(8, 8), value.part2);
 67→    BinaryPrimitives.WriteUInt64LittleEndian(bytes.AsSpan(16, 8), value.part3);
 68→    BinaryPrimitives.WriteUInt64LittleEndian(bytes.AsSpan(24, 8), value.part4);
 69→    return bytes;
 70→  }
 71→
 72→  public static byte[]? AsManagedBytes(this Native.OptionChangeBytes option)
 73→  {
 74→    try
 75→    {
 76→      if(option.IsSome)
 77→      {
 78→        using var change = option.AsSome();
 79→        return change.AsManagedBytes();
 80→      }
 81→
 82→      return null;
 83→    }
 84→    finally
 85→    {
 86→      option.Dispose();
 87→    }
 88→  }
 89→
 90→  public static byte[] ToArrayAndDispose(this Native.VecU8 vec) => CopyVecU8(vec, disposeVec: true);
 91→
 92→  public static IReadOnlyList<string> AsStringList(this Native.VecUtf8String vec)
 93→  {
 94→    var length = vec.Count;
 95→    if(length == 0)
 96→    {
 97→      return Array.Empty<string>();
 98→    }
 99→
100→    var result = new List<string>(length);
101→    for(var i = 0; i < length; i++)
102→    {
103→      using var managed = vec[i];
104→      try
105→      {
106→        result.Add(managed.String);
107→      }
108→      finally
109→      {
110→        managed.Dispose();
111→      }
112→    }
113→
114→    return result;
115→  }
116→
117→  public static IReadOnlyList<Native.ChangeHashBytes> AsHashList(this Native.VecChangeHashBytes vec)
118→  {
119→    if(vec.Count == 0)
120→    {
121→      return Array.Empty<Native.ChangeHashBytes>();
122→    }
123→
124→    var length = vec.Count;
125→    var result = new Native.ChangeHashBytes[length];
126→    for(var i = 0; i < length; i++)
127→    {
128→      result[i] = vec[i];
129→    }
130→
131→    return result;
132→  }
133→
134→  public static IReadOnlyList<byte[]> AsByteArrayList(this Native.VecChangeBytes vec)
135→  {
136→    if(vec.Count == 0)
137→    {
138→      return Array.Empty<byte[]>();
139→    }
140→
141→    return CopyChangeBytesVector(vec);
142→  }
143→
144→  
145→  
146→  static byte[] CopyVecU8(Native.VecU8 vec, bool disposeVec)
147→  {
148→    try
149→    {
150→      if(vec._ptr == IntPtr.Zero || vec._len == 0)
151→      {
152→        return Array.Empty<byte>();
153→      }
154→
155→      var length = checked((int)vec._len);
156→      var buffer = new byte[length];
157→      Marshal.Copy(vec._ptr, buffer, 0, length);
158→      return buffer;
159→    }
160→    finally
161→    {
162→      if(disposeVec)
163→      {
164→        vec.Dispose();
165→      }
166→    }
167→  }
168→
169→  static byte[][] CopyChangeBytesVector(Native.VecChangeBytes vec)
170→  {
171→    var count = vec.Count;
172→    if(count == 0)
173→    {
174→      return Array.Empty<byte[]>();
175→    }
176→
177→    var result = new byte[count][];
178→    var structSize = Marshal.SizeOf<Native.ChangeBytes.Unmanaged>();
179→
180→    for(var i = 0; i < count; i++)
181→    {
182→      var elementPtr = IntPtr.Add(vec._ptr, i * structSize);
183→      var unmanaged = Marshal.PtrToStructure<Native.ChangeBytes.Unmanaged>(elementPtr);
184→      if(unmanaged.bytes._ptr == IntPtr.Zero || unmanaged.bytes._len == 0)
185→      {
186→        result[i] = Array.Empty<byte>();
187→        continue;
188→      }
189→
190→      var length = checked((int)unmanaged.bytes._len);
191→      var target = new byte[length];
192→      Marshal.Copy(unmanaged.bytes._ptr, target, 0, length);
193→      result[i] = target;
194→    }
195→
196→    return result;
197→  }
198→}

