 10→namespace Server.Api.Services;
 11→
 12→/// <summary>
 13→/// Manages one <see cref="Repo"/> instance per registered app type.
 14→/// Each repo gets its own <see cref="FileSystemStorageAdapter"/> in an isolated subdirectory
 15→/// and optionally a network adapter for client sync.
 16→/// </summary>
 17→[PublicAPI]
 18→public sealed class ServerRepoManager : IHostedService
 19→{
 20→  readonly ServerRepoOptions _options;
 21→  readonly ILoggerFactory _loggerFactory;
 22→  readonly ILogger<ServerRepoManager> _logger;
 23→  readonly ConcurrentDictionary<string, RepoEntry> _repos = new(StringComparer.OrdinalIgnoreCase);
 24→  readonly Func<string, INetworkAdapter>? _networkAdapterFactory;
 25→
 26→  bool _started;
 27→  bool _stopped;
 28→
 29→  /// <summary>
 30→  /// Initializes a new instance of the <see cref="ServerRepoManager"/> class.
 31→  /// </summary>
 32→  /// <param name="options">Server repo configuration.</param>
 33→  /// <param name="loggerFactory">Logger factory.</param>
 34→  /// <param name="networkAdapterFactory">Optional factory that creates a network adapter for each app type.</param>
 35→  public ServerRepoManager(
 36→    IOptions<ServerRepoOptions> options,
 37→    ILoggerFactory loggerFactory,
 38→    Func<string, INetworkAdapter>? networkAdapterFactory = null)
 39→  {
 40→    ArgumentNullException.ThrowIfNull(options);
 41→    ArgumentNullException.ThrowIfNull(loggerFactory);
 42→
 43→    _options = options.Value;
 44→    _loggerFactory = loggerFactory;
 45→    _logger = loggerFactory.CreateLogger<ServerRepoManager>();
 46→    _networkAdapterFactory = networkAdapterFactory;
 47→  }
 48→
 49→  /// <inheritdoc />
 50→  public Task StartAsync(CancellationToken cancellationToken)
 51→  {
 52→    _logger.LogInformation("Starting ServerRepoManager. StorageBaseDirectory={StorageBaseDirectory}",
 53→      _options.StorageBaseDirectory);
 54→
 55→    Directory.CreateDirectory(_options.StorageBaseDirectory);
 56→    _started = true;
 57→
 58→    return Task.CompletedTask;
 59→  }
 60→
 61→  /// <inheritdoc />
 62→  public async Task StopAsync(CancellationToken cancellationToken)
 63→  {
 64→    if(_stopped)
 65→      return;
 66→
 67→    _stopped = true;
 68→    _started = false;
 69→
 70→    _logger.LogInformation("Stopping ServerRepoManager. Flushing and disposing {Count} repos.",
 71→      _repos.Count);
 72→
 73→    foreach(var kvp in _repos)
 74→    {
 75→      var entry = kvp.Value;
 76→      try
 77→      {
 78→        _logger.LogInformation("Flushing repo for app type '{AppType}'", kvp.Key);
 79→        await entry.Repo.Flush().ConfigureAwait(false);
 80→        entry.Repo.Dispose();
 81→        entry.Storage.Dispose();
 82→      }
 83→      catch(Exception ex)
 84→      {
 85→        _logger.LogError(ex, "Error disposing repo for app type '{AppType}'", kvp.Key);
 86→      }
 87→    }
 88→
 89→    _repos.Clear();
 90→    _logger.LogInformation("ServerRepoManager stopped.");
 91→  }
 92→
 93→  /// <summary>
 94→  /// Gets or creates a <see cref="Repo"/> instance for the specified app type.
 95→  /// Each app type gets isolated storage and an optional network adapter.
 96→  /// </summary>
 97→  /// <param name="appType">The app type identifier (e.g., "text-editor", "drawing").</param>
 98→  /// <returns>The repo instance for the app type.</returns>
 99→  /// <exception cref="InvalidOperationException">Thrown if the manager has not been started.</exception>
100→  public Repo GetRepo(string appType)
101→  {
102→    ThrowIfNotStarted();
103→    ArgumentException.ThrowIfNullOrWhiteSpace(appType);
104→
105→    var entry = _repos.GetOrAdd(appType, CreateRepoEntry);
106→    return entry.Repo;
107→  }
108→
109→  /// <summary>
110→  /// Lists all document IDs stored for the specified app type by scanning the storage directory.
111→  /// </summary>
112→  /// <param name="appType">The app type identifier.</param>
113→  /// <returns>A list of document IDs found in storage.</returns>
114→  public IReadOnlyList<string> ListDocuments(string appType)
115→  {
116→    ArgumentException.ThrowIfNullOrWhiteSpace(appType);
117→
118→    var storageDir = GetStorageDirectory(appType);
119→
120→    if(!Directory.Exists(storageDir))
121→      return [];
122→
123→    var documentIds = new HashSet<string>();
124→
125→    // Scan the sharded directory structure:
126→    // storageDir/AB/CREST/... → document ID "ABCREST"
127→    try
128→    {
129→      foreach(var shardDir in Directory.GetDirectories(storageDir))
130→      {
131→        var shardName = Path.GetFileName(shardDir);
132→        if(shardName.Length != 2)
133→          continue;
134→
135→        foreach(var docDir in Directory.GetDirectories(shardDir))
136→        {
137→          var remaining = Path.GetFileName(docDir);
138→          var documentId = shardName + remaining;
139→          documentIds.Add(documentId);
140→        }
141→      }
142→    }
143→    catch(Exception ex) when(ex is DirectoryNotFoundException or UnauthorizedAccessException)
144→    {
145→      _logger.LogWarning(ex, "Error scanning storage directory for app type '{AppType}'", appType);
146→    }
147→
148→    return [.. documentIds];
149→  }
150→
151→  /// <summary>
152→  /// Gets all registered app types.
153→  /// </summary>
154→  public IReadOnlyList<string> GetAppTypes()
155→  {
156→    return [.. _repos.Keys];
157→  }
158→
159→  /// <summary>
160→  /// Gets status information for all registered repos.
161→  /// </summary>
162→  public IReadOnlyDictionary<string, RepoStatusInfo> GetRepoStatus()
163→  {
164→    var result = new Dictionary<string, RepoStatusInfo>(StringComparer.OrdinalIgnoreCase);
165→
166→    foreach(var kvp in _repos)
167→    {
168→      var entry = kvp.Value;
169→      result[kvp.Key] = new RepoStatusInfo
170→      {
171→        PeerId = entry.Repo.PeerId,
172→        StorageDirectory = entry.StorageDirectory,
173→        DocumentCount = ListDocuments(kvp.Key).Count,
174→        PeerCount = entry.Repo.Peers.Count
175→      };
176→    }
177→
178→    return result;
179→  }
180→
181→  RepoEntry CreateRepoEntry(string appType)
182→  {
183→    var storageDir = GetStorageDirectory(appType);
184→    Directory.CreateDirectory(storageDir);
185→
186→    _logger.LogInformation("Creating repo for app type '{AppType}' with storage at '{StorageDir}'",
187→      appType, storageDir);
188→
189→    var storage = new FileSystemStorageAdapter(storageDir);
190→
191→    var networkAdapters = new List<INetworkAdapter>();
192→    if(_networkAdapterFactory is not null)
193→    {
194→      var adapter = _networkAdapterFactory(appType);
195→      networkAdapters.Add(adapter);
196→    }
197→
198→    var repo = new Repo(new RepoConfig
199→    {
200→      Storage = storage,
201→      NetworkAdapters = networkAdapters.Count > 0 ? networkAdapters : null
202→    });
203→
204→    _logger.LogInformation("Repo created for app type '{AppType}'. PeerId={PeerId}",
205→      appType, repo.PeerId);
206→
207→    return new RepoEntry(repo, storage, storageDir);
208→  }
209→
210→  string GetStorageDirectory(string appType) =>
211→    Path.Combine(_options.StorageBaseDirectory, appType);
212→
213→  void ThrowIfNotStarted()
214→  {
215→    if(!_started || _stopped)
216→      throw new InvalidOperationException("ServerRepoManager has not started or has been stopped.");
217→  }
218→
219→  sealed record RepoEntry(Repo Repo, FileSystemStorageAdapter Storage, string StorageDirectory);
220→}
221→
222→/// <summary>
223→/// Status information for a single repo instance.
224→/// </summary>
225→[PublicAPI]
226→[ExcludeFromCodeCoverage]
227→public sealed record RepoStatusInfo
228→{
229→  public required PeerId PeerId { get; init; }
230→
231→  public required string StorageDirectory { get; init; }
232→
233→  public required int DocumentCount { get; init; }
234→
235→  public required int PeerCount { get; init; }
236→}
