 1→using MessagePack;
 2→using MessagePack.Resolvers;
 3→using Six.Automerge.Repository.Network.SignalR.Server;
 4→using Server.Api.Hubs;
 5→using Server.Api.Services;
 6→
 7→var builder = WebApplication.CreateBuilder(args);
 8→
 9→// Add service defaults (includes service discovery, health checks, etc.)
10→builder.AddServiceDefaults();
11→
12→// Add SignalR with MessagePack (LZ4 compression) + JSON protocols
13→builder.Services
14→  .AddSignalR()
15→  .AddMessagePackProtocol(options =>
16→  {
17→    options.SerializerOptions = MessagePackSerializerOptions.Standard
18→      .WithCompression(MessagePackCompression.Lz4Block)
19→      .WithResolver(ContractlessStandardResolver.Instance);
20→  })
21→  .AddJsonProtocol();
22→
23→// Add server-side repo infrastructure
24→builder.Services.AddServerRepoManager(options =>
25→{
26→  // Configure from environment variable with fallback to default
27→  var envDir = Environment.GetEnvironmentVariable("SERVER_STORAGE_DIR");
28→  if(!string.IsNullOrWhiteSpace(envDir))
29→  {
30→    options.StorageBaseDirectory = envDir;
31→  }
32→});
33→
34→builder.Services
35→  .AddCors(options =>
36→  {
37→    options.AddPolicy("AllowAll", policy =>
38→    {
39→      policy
40→        .SetIsOriginAllowed(_ => true)
41→        .AllowAnyMethod()
42→        .AllowAnyHeader()
43→        .AllowCredentials();
44→    });
45→  });
46→
47→if(builder.Environment.IsDevelopment())
48→{
49→  builder.Services.AddOpenApi();
50→}
51→
52→var app = builder.Build();
53→
54→app.UseHttpsRedirection();
55→app.UseCors("AllowAll");
56→
57→app.MapDefaultEndpoints();
58→
59→// Map per-app collaborative hubs (messages route through server Repo)
60→app.MapHub<TextEditorHub>("/hubs/text-editor");
61→app.MapHub<EditorHub>("/hubs/editor");
62→app.MapHub<DrawingHub>("/hubs/drawing");
63→app.MapHub<TaskBoardHub>("/hubs/task-board");
64→
65→// Legacy: keep /hubs/documents for backward compatibility during migration
66→app.MapHub<DocumentsHub>("/hubs/documents");
67→
68→// Hub health check endpoint with repo status
69→app.MapGet("/hubs/health", (ServerRepoManager repoManager) =>
70→{
71→  var status = repoManager.GetRepoStatus();
72→  return Results.Ok(new
73→  {
74→    status = "healthy",
75→    hubs = new[]
76→    {
77→      $"/hubs/{TextEditorHub.AppTypeId}",
78→      $"/hubs/{EditorHub.AppTypeId}",
79→      $"/hubs/{DrawingHub.AppTypeId}",
80→      $"/hubs/{TaskBoardHub.AppTypeId}",
81→      "/hubs/documents (legacy)"
82→    },
83→    repos = status
84→  });
85→});
86→
87→if(app.Environment.IsDevelopment())
88→{
89→  app.MapOpenApi();
90→}
91→
92→await app.RunAsync();
