 54→  public Task WhenReady() => Task.CompletedTask;
 55→
 56→  /// <inheritdoc />
 57→  public event EventHandler<PeerCandidateEventArgs>? PeerCandidate;
 58→
 59→  /// <inheritdoc />
 60→  public event EventHandler<PeerDisconnectedEventArgs>? PeerDisconnected;
 61→
 62→  /// <inheritdoc />
 63→  public event EventHandler<MessageReceivedEventArgs>? MessageReceived;
 64→
 65→  /// <inheritdoc />
 66→  public event EventHandler? Closed;
 67→
 68→  /// <inheritdoc />
 69→  public void Connect(PeerId peerId, PeerMetadata? metadata = null)
 70→  {
 71→    // No-op: server adapter is always ready.
 72→    // It doesn't need to establish an outbound connection.
 73→    _logger.LogDebug("Connect called on server adapter (no-op). PeerId={PeerId}", peerId);
 74→  }
 75→
 76→  /// <inheritdoc />
 77→  public void Send(IRepoMessage message)
 78→  {
 79→    if(_disposed)
 80→      return;
 81→
 82→    ArgumentNullException.ThrowIfNull(message);
 83→
 84→    _ = SendAsyncInternal(message);
 85→  }
 86→
 87→  /// <inheritdoc />
 88→  public Task Disconnect()
 89→  {
 90→    _isReady = false;
 91→    _peerToConnection.Clear();
 92→    _connectionToPeer.Clear();
 93→
 94→    _logger.LogInformation("Server network adapter disconnected.");
 95→
 96→    Closed?.Invoke(this, EventArgs.Empty);
 97→
 98→    return Task.CompletedTask;
 99→  }
100→
101→  /// <summary>
102→  /// Called by the hub when a client completes handshake.
103→  /// Tracks the peer-to-connection mapping and raises <see cref="PeerCandidate"/>.
104→  /// </summary>
105→  /// <param name="connectionId">The SignalR connection ID.</param>
106→  /// <param name="peerId">The peer ID from the handshake.</param>
107→  /// <param name="metadata">Optional peer metadata.</param>
108→  public void OnClientConnected(string connectionId, PeerId peerId, PeerMetadata? metadata)
109→  {
110→    _peerToConnection[peerId] = connectionId;
111→    _connectionToPeer[connectionId] = peerId;
112→
113→    _logger.LogInformation("Client connected to server adapter. PeerId={PeerId}, ConnectionId={ConnectionId}",
114→      peerId, connectionId);
115→
116→    PeerCandidate?.Invoke(this, new PeerCandidateEventArgs
117→    {
118→      PeerId = peerId,
119→      Metadata = metadata
120→    });
121→  }
122→
123→  /// <summary>
124→  /// Called by the hub when a client disconnects.
125→  /// Removes the mapping and raises <see cref="PeerDisconnected"/>.
126→  /// </summary>
127→  /// <param name="connectionId">The SignalR connection ID.</param>
128→  /// <param name="peerId">The peer ID.</param>
129→  public void OnClientDisconnected(string connectionId, PeerId peerId)
130→  {
131→    _peerToConnection.TryRemove(peerId, out _);
132→    _connectionToPeer.TryRemove(connectionId, out _);
133→
134→    _logger.LogInformation("Client disconnected from server adapter. PeerId={PeerId}, ConnectionId={ConnectionId}",
135→      peerId, connectionId);
136→
137→    PeerDisconnected?.Invoke(this, new PeerDisconnectedEventArgs
138→    {
139→      PeerId = peerId
140→    });
141→  }
142→
143→  /// <summary>
144→  /// Called by the hub when a client sends a message.
145→  /// Deserializes and raises <see cref="MessageReceived"/> for the server-side Repo.
146→  /// </summary>
147→  /// <param name="senderId">The peer ID of the sender.</param>
148→  /// <param name="message">The deserialized repo message.</param>
149→  public void OnClientMessage(PeerId senderId, IRepoMessage message)
150→  {
151→    _logger.LogDebug("Received message from client. SenderId={SenderId}, MessageType={MessageType}, DocumentId={DocumentId}",
152→      senderId, message.MessageType, message.DocumentId?.Value);
153→
154→    MessageReceived?.Invoke(this, new MessageReceivedEventArgs
155→    {
156→      Message = message
157→    });
158→  }
159→
160→  /// <summary>
161→  /// Gets the number of currently connected peers.
162→  /// </summary>
163→  public int GetConnectedPeerCount() => _peerToConnection.Count;
164→
165→  /// <summary>
166→  /// Tries to look up the connection ID for a peer.
167→  /// </summary>
168→  /// <param name="peerId">The peer ID to look up.</param>
169→  /// <param name="connectionId">The connection ID, if found.</param>
170→  /// <returns>True if the peer has a known connection.</returns>
171→  public bool TryGetConnectionId(PeerId peerId, out string? connectionId)
172→  {
173→    return _peerToConnection.TryGetValue(peerId, out connectionId);
174→  }
175→
176→  async Task SendAsyncInternal(IRepoMessage message)
177→  {
178→    try
179→    {
180→      var documentId = message.DocumentId;
181→
182→      if(documentId is null)
183→      {
184→        _logger.LogWarning("Cannot send message: DocumentId is null. MessageType={MessageType}", message.MessageType);
185→        return;
186→      }
187→
188→      if(message.SenderId is null)
189→      {
190→        _logger.LogWarning("Cannot send message: SenderId is null. MessageType={MessageType}", message.MessageType);
191→        return;
192→      }
193→
194→      // Create MessageDto for the wire
195→      var messageData = GetMessageData(message);
196→      var messageDto = MessageDto.FromRepoMessage(message, messageData ?? []);
197→
198→      _logger.LogDebug("Sending {MessageType} to group {DocumentId}. SenderId={SenderId}",
199→        message.MessageType, documentId.Value.Value, message.SenderId);
200→
201→      // Broadcast to all clients subscribed to this document group
202→      await _hubContext.Clients.Group(documentId.Value.Value).OnReceiveMessage(messageDto);
203→    }
204→    catch(Exception ex)
205→    {
206→      _logger.LogError(ex, "Failed to send message type {MessageType} for document {DocumentId}",
207→        message.MessageType, message.DocumentId?.Value);
208→    }
209→  }
210→
211→  static byte[]? GetMessageData(IRepoMessage message)
212→  {
213→    return message switch
214→    {
215→      SyncMessage sync => sync.Data,
216→      RequestMessage request => request.Data,
217→      EphemeralMessage ephemeral => ephemeral.Data,
218→      DocumentUnavailableMessage => [],
219→      DocumentSnapshotMessage snapshot => snapshot.Data,
220→      _ => null
221→    };
222→  }
223→
224→  /// <inheritdoc />
225→  public void Dispose()
226→  {
227→    if(_disposed)
228→      return;
229→
230→    _disposed = true;
231→    _isReady = false;
232→    _peerToConnection.Clear();
233→    _connectionToPeer.Clear();
234→  }
235→}
