  3→/// <summary>
  4→/// SignalR hub for Automerge document synchronization.
  5→/// </summary>
  6→/// <remarks>
  7→/// This hub provides real-time message routing between connected peers for document collaboration.
  8→/// Messages are organized into document-specific groups, ensuring efficient targeted delivery.
  9→///
 10→/// <para>
 11→/// <strong>Key Features:</strong>
 12→/// <list type="bullet">
 13→///   <item><description>Document-based group management (one group per document ID)</description></item>
 14→///   <item><description>Automatic subscription on first message send</description></item>
 15→///   <item><description>Echo prevention (senders don't receive their own messages)</description></item>
 16→///   <item><description>Graceful error handling with comprehensive logging</description></item>
 17→/// </list>
 18→/// </para>
 19→///
 20→/// <para>
 21→/// <strong>Usage Example (ASP.NET Core):</strong>
 22→/// <code>
 23→/// app.MapHub&lt;DocumentsHub&gt;("/hubs/documents");
 24→/// </code>
 25→/// </para>
 26→/// </remarks>
 27→[PublicAPI]
 28→public class DocumentsHub : Hub<IDocumentsHubClient>, IDocumentsHub
 29→{
 30→  readonly ILogger<DocumentsHub> _logger;
 31→
 32→  /// <summary>
 33→  /// Initializes a new instance of the <see cref="DocumentsHub"/> class.
 34→  /// </summary>
 35→  /// <param name="logger">The logger instance.</param>
 36→  public DocumentsHub(ILogger<DocumentsHub> logger)
 37→  {
 38→    _logger = logger ?? throw new ArgumentNullException(nameof(logger));
 39→  }
 40→
 41→  /// <inheritdoc />
 42→  public async Task<PeerHandshakeDto> Handshake(PeerHandshakeDto handshake)
 43→  {
 44→    try
 45→    {
 46→      _logger.LogInformation(
 47→        "Peer handshake: PeerId={PeerId}, ConnectionId={ConnectionId}, IsEphemeral={IsEphemeral}",
 48→        handshake.PeerId,
 49→        Context.ConnectionId,
 50→        handshake.Metadata?.IsEphemeral ?? false);
 51→
 52→      // Store peer ID in connection context for later use
 53→      Context.Items["PeerId"] = handshake.PeerId;
 54→
 55→      // Broadcast peer join to all OTHER clients (not the joining client itself)
 56→      // This enables peer discovery for document synchronization
 57→      await Clients.Others.OnPeerJoined(handshake);
 58→
 59→      _logger.LogDebug(
 60→        "Peer join broadcasted to all other clients: PeerId={PeerId}",
 61→        handshake.PeerId);
 62→    }
 63→    catch (Exception ex)
 64→    {
 65→      _logger.LogError(ex, "Error during handshake for ConnectionId={ConnectionId}", Context.ConnectionId);
 66→    }
 67→
 68→    // Relay-mode hub has no Repo; return a stable server identity so clients
 69→    // know who their direct peer is.
 70→    return PeerHandshakeDto.Create(new PeerId($"relay-{Context.ConnectionId}"), null);
 71→  }
 72→
 73→  /// <inheritdoc />
 74→  public async Task SubscribeToDocument(string documentId)
 75→  {
 76→    try
 77→    {
 78→      if (string.IsNullOrEmpty(documentId))
 79→      {
 80→        _logger.LogWarning("Attempt to subscribe with null/empty documentId. ConnectionId={ConnectionId}",
 81→          Context.ConnectionId);
 82→        return;
 83→      }
 84→
 85→      await Groups.AddToGroupAsync(Context.ConnectionId, documentId);
 86→
 87→      _logger.LogInformation(
 88→        "Peer subscribed to document: DocumentId={DocumentId}, ConnectionId={ConnectionId}, PeerId={PeerId}",
 89→        documentId,
 90→        Context.ConnectionId,
 91→        Context.Items.TryGetValue("PeerId", out var peerId) ? peerId : "unknown");
 92→    }
 93→    catch (Exception ex)
 94→    {
 95→      _logger.LogError(ex, "Error subscribing to document {DocumentId} for ConnectionId={ConnectionId}",
 96→        documentId, Context.ConnectionId);
 97→    }
 98→  }
 99→
100→  /// <inheritdoc />
101→  public async Task UnsubscribeFromDocument(string documentId)
102→  {
103→    try
104→    {
105→      if (string.IsNullOrEmpty(documentId))
106→      {
107→        _logger.LogWarning("Attempt to unsubscribe with null/empty documentId. ConnectionId={ConnectionId}",
108→          Context.ConnectionId);
109→        return;
110→      }
111→
112→      await Groups.RemoveFromGroupAsync(Context.ConnectionId, documentId);
113→
114→      _logger.LogInformation(
115→        "Peer unsubscribed from document: DocumentId={DocumentId}, ConnectionId={ConnectionId}, PeerId={PeerId}",
116→        documentId,
117→        Context.ConnectionId,
118→        Context.Items.TryGetValue("PeerId", out var peerId) ? peerId : "unknown");
119→    }
120→    catch (Exception ex)
121→    {
122→      _logger.LogError(ex, "Error unsubscribing from document {DocumentId} for ConnectionId={ConnectionId}",
123→        documentId, Context.ConnectionId);
124→    }
125→  }
126→
127→  /// <inheritdoc />
128→  public async Task SendMessage(MessageDto message)
129→  {
130→    try
131→    {
132→      if (string.IsNullOrEmpty(message.DocumentId))
133→      {
134→        _logger.LogWarning(
135→          "Received message with null/empty DocumentId. MessageType={MessageType}, SenderId={SenderId}, ConnectionId={ConnectionId}",
136→          message.MessageType,
137→          message.SenderId,
138→          Context.ConnectionId);
139→        return;
140→      }
141→
142→      _logger.LogInformation(
143→        "Received message from client. DocumentId={DocumentId}, MessageType={MessageType}, SenderId={SenderId}, ConnectionId={ConnectionId}",
144→        message.DocumentId,
145→        message.MessageType,
146→        message.SenderId,
147→        Context.ConnectionId);
148→
149→      _logger.LogDebug(
150→        "Routing message: DocumentId={DocumentId}, MessageType={MessageType}, SenderId={SenderId}, ConnectionId={ConnectionId}, DataSize={DataSize}",
151→        message.DocumentId,
152→        message.MessageType,
153→        message.SenderId,
154→        Context.ConnectionId,
155→        message.Data?.Length ?? 0);
156→
157→      // Auto-subscribe sender to document group if not already subscribed
158→      // This ensures messages are delivered even if explicit subscription wasn't called
159→      await Groups.AddToGroupAsync(Context.ConnectionId, message.DocumentId);
160→
161→      // Broadcast to all group members EXCEPT the sender (prevents echo-back)
162→      await Clients.OthersInGroup(message.DocumentId).OnReceiveMessage(message);
163→
164→      _logger.LogDebug(
165→        "Message routed successfully: DocumentId={DocumentId}, MessageType={MessageType}",
166→        message.DocumentId,
167→        message.MessageType);
168→    }
169→    catch (Exception ex)
170→    {
171→      _logger.LogError(ex,
172→        "Error routing message: DocumentId={DocumentId}, MessageType={MessageType}, SenderId={SenderId}, ConnectionId={ConnectionId}",
173→        message.DocumentId,
174→        message.MessageType,
175→        message.SenderId,
176→        Context.ConnectionId);
177→    }
178→  }
179→
180→  /// <summary>
181→  /// Called when a new connection is established.
182→  /// </summary>
183→  public override Task OnConnectedAsync()
184→  {
185→    _logger.LogInformation("Client connected: ConnectionId={ConnectionId}", Context.ConnectionId);
186→    return base.OnConnectedAsync();
187→  }
188→
189→  /// <summary>
190→  /// Called when a connection is terminated.
191→  /// </summary>
192→  /// <param name="exception">The exception that caused the disconnect, if any.</param>
193→  public override async Task OnDisconnectedAsync(Exception? exception)
194→  {
195→    var peerId = Context.Items.TryGetValue("PeerId", out var id) ? id?.ToString() : null;
196→
197→    if (exception is not null)
198→    {
199→      _logger.LogWarning(exception,
200→        "Client disconnected with error: ConnectionId={ConnectionId}, PeerId={PeerId}",
201→        Context.ConnectionId,
