 11→
 12→/// <summary>
 13→/// Hub filter that intercepts <see cref="DocumentsHub"/> events to forward them
 14→/// to the server's <see cref="SignalRServerNetworkAdapter"/>.
 15→/// This enables the server to participate in Automerge document synchronization.
 16→/// </summary>
 17→[PublicAPI]
 18→public sealed class ServerDocumentsHubFilter : IHubFilter
 19→{
 20→  readonly SignalRServerNetworkAdapter _adapter;
 21→  readonly ILogger<ServerDocumentsHubFilter> _logger;
 22→
 23→  public ServerDocumentsHubFilter(
 24→    SignalRServerNetworkAdapter adapter,
 25→    ILogger<ServerDocumentsHubFilter> logger)
 26→  {
 27→    _adapter = adapter ?? throw new ArgumentNullException(nameof(adapter));
 28→    _logger = logger ?? throw new ArgumentNullException(nameof(logger));
 29→  }
 30→
 31→  /// <inheritdoc />
 32→  public async ValueTask<object?> InvokeMethodAsync(
 33→    HubInvocationContext invocationContext,
 34→    Func<HubInvocationContext, ValueTask<object?>> next)
 35→  {
 36→    var result = await next(invocationContext);
 37→
 38→    // After the base hub method executes, forward events to the server adapter
 39→    switch(invocationContext.HubMethodName)
 40→    {
 41→      case "Handshake" when invocationContext.HubMethodArguments.Count > 0
 42→        && invocationContext.HubMethodArguments[0] is PeerHandshakeDto handshake:
 43→        OnHandshake(invocationContext.Context, handshake);
 44→        break;
 45→
 46→      case "SendMessage" when invocationContext.HubMethodArguments.Count > 0
 47→        && invocationContext.HubMethodArguments[0] is MessageDto message:
 48→        OnMessage(message);
 49→        break;
 50→    }
 51→
 52→    return result;
 53→  }
 54→
 55→  /// <inheritdoc />
 56→  public Task OnConnectedAsync(
 57→    HubLifetimeContext context,
 58→    Func<HubLifetimeContext, Task> next)
 59→  {
 60→    _logger.LogDebug("Client connected. ConnectionId={ConnectionId}",
 61→      context.Context.ConnectionId);
 62→
 63→    return next(context);
 64→  }
 65→
 66→  /// <inheritdoc />
 67→  public async Task OnDisconnectedAsync(
 68→    HubLifetimeContext context,
 69→    Exception? exception,
 70→    Func<HubLifetimeContext, Exception?, Task> next)
 71→  {
 72→    // Get peer ID before base call
 73→    var peerId = context.Context.Items.TryGetValue("PeerId", out var id) ? id?.ToString() : null;
 74→
 75→    await next(context, exception);
 76→
 77→    // Forward to server adapter
 78→    if(!string.IsNullOrEmpty(peerId))
 79→    {
 80→      _logger.LogInformation(
 81→        "Forwarding client disconnect to server adapter. PeerId={PeerId}, ConnectionId={ConnectionId}",
 82→        peerId, context.Context.ConnectionId);
 83→
 84→      _adapter.OnClientDisconnected(context.Context.ConnectionId, new PeerId(peerId));
 85→    }
 86→  }
 87→
 88→  void OnHandshake(HubCallerContext context, PeerHandshakeDto handshake)
 89→  {
 90→    var peerId = new PeerId(handshake.PeerId);
 91→    var metadata = handshake.Metadata?.ToPeerMetadata();
 92→
 93→    _logger.LogInformation(
 94→      "Forwarding client handshake to server adapter. PeerId={PeerId}, ConnectionId={ConnectionId}",
 95→      peerId, context.ConnectionId);
 96→
 97→    _adapter.OnClientConnected(context.ConnectionId, peerId, metadata);
 98→  }
 99→
100→  void OnMessage(MessageDto message)
101→  {
102→    if(string.IsNullOrEmpty(message.SenderId) || string.IsNullOrEmpty(message.DocumentId))
103→      return;
104→
105→    var repoMessage = DeserializeMessage(message);
106→
107→    if(repoMessage is not null)
108→    {
109→      _logger.LogDebug(
110→        "Forwarding client message to server adapter. MessageType={MessageType}, DocumentId={DocumentId}, SenderId={SenderId}",
111→        message.MessageType, message.DocumentId, message.SenderId);
112→
113→      _adapter.OnClientMessage(new PeerId(message.SenderId), repoMessage);
114→    }
115→  }
116→
117→  static IRepoMessage? DeserializeMessage(MessageDto messageDto)
118→  {
119→    var senderId = new PeerId(messageDto.SenderId);
120→
121→    return messageDto.MessageType switch
122→    {
123→      "sync" => new SyncMessage
124→      {
125→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
126→        Data = messageDto.Data,
127→        SenderId = senderId
128→      },
129→      "request" => new RequestMessage
130→      {
131→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
132→        Data = messageDto.Data,
133→        SenderId = senderId
134→      },
135→      "doc-unavailable" => new DocumentUnavailableMessage
136→      {
137→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
138→        SenderId = senderId
139→      },
140→      "doc-snapshot" => new DocumentSnapshotMessage
141→      {
142→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
143→        Data = messageDto.Data ?? [],
144→        SenderId = senderId
145→      },
146→      _ => null
147→    };
148→  }
149→}
