  static AutomergeProp? ConvertOptionalProp(Native.OptionAutomergeProp option, bool disposeOption = true)
  {
    if(!option.IsSome)
    {
      if(disposeOption)
      {
        option.Dispose();
      }
      return null;
    }

    var prop = option.AsSome();
    var converted = ConvertProp(prop, dispose: disposeOption);
    if(disposeOption)
